'Wallet_Payment_Method_Missing' => 'वॉलेट भुगतान विधि मौजूद नहीं है',
'Wallet_Payment_Method_Missing_Help' => 'ठीक "Wallet" नाम की कोई भुगतान विधि नहीं मिली। POS का वॉलेट भुगतान इसी नाम से पहचाना जाता है, इसलिए जब तक आप यहाँ "Wallet" नाम की भुगतान विधि नहीं जोड़ते, ग्राहक अपने वॉलेट से भुगतान नहीं कर सकते:',

'Show_Previous_Dues_Line' => 'पिछली बकाया राशि की पंक्ति दिखाएँ',
'Show_Previous_Dues_Line_Desc' => 'इस बिक्री से पहले ग्राहक पर बकाया राशि। केवल तभी प्रिंट होती है जब शून्य से अधिक हो।',
'Show_Net_Balance_Line' => 'कुल शेष की पंक्ति दिखाएँ',
'Show_Net_Balance_Line_Desc' => 'पिछली बकाया राशि और इस बिक्री की शेष देय राशि का योग। केवल तभी प्रिंट होती है जब पिछली बकाया राशि शून्य से अधिक हो।',

'QZ_Tray_Printer' => 'QZ Tray (इस कंप्यूटर का प्रिंटर)',
'QZ_Printer_Name_Hint' => 'प्रिंटर का नाम, जैसा QZ Tray चलाने वाले कंप्यूटर पर दिखता है। उस कंप्यूटर का डिफ़ॉल्ट प्रिंटर उपयोग करने के लिए खाली छोड़ें। प्रिंटर खोजने के लिए ⟳ क्लिक करें।',
'QZ_Not_Running' => 'इस कंप्यूटर पर QZ Tray नहीं चल रहा है। इसे qz.io से इंस्टॉल करें और चालू रखें, फिर QZ के पूछने पर इस वेबसाइट को अनुमति दें।',
'Detect_Printers' => 'प्रिंटर खोजें',
'QZ_Download_Cert' => 'प्रमाणपत्र डाउनलोड करें (override.crt)',
'QZ_Setup_Title' => 'QZ Tray से प्रिंटिंग कैसे सेट करें (एक बार, लेबल प्रिंट करने वाले हर कंप्यूटर पर)',
'QZ_Step_Install' => '1. इस कंप्यूटर पर QZ Tray इंस्टॉल करें — इसे qz.io से मुफ़्त डाउनलोड करें, फिर चालू करके चलता रहने दें (यह Windows में सिस्टम ट्रे में या macOS में मेनू बार में रहता है)।',
'QZ_Step_Connect' => '2. अपना लेबल प्रिंटर USB से जोड़ें और जाँचें कि यह ऑपरेटिंग सिस्टम में इंस्टॉल है (Windows: Settings > Printers & scanners — macOS: System Settings > Printers & Scanners)।',
'QZ_Step_Detect' => '3. इस कंप्यूटर के प्रिंटर खोजने के लिए ऊपर "प्रिंटर का नाम" के पास ⟳ बटन क्लिक करें, फिर अपना लेबल प्रिंटर चुनें। कंप्यूटर का डिफ़ॉल्ट प्रिंटर उपयोग करने के लिए फ़ील्ड खाली छोड़ें।',
'QZ_Step_Cert' => '4. बिना अनुमति पॉपअप के प्रिंट करने के लिए नीचे दिया प्रमाणपत्र डाउनलोड करें और उसे override.crt नाम से QZ Tray के इंस्टॉलेशन फ़ोल्डर में कॉपी करें (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray)। फिर QZ Tray बंद करके दोबारा चालू करें।',
'QZ_Step_Test' => '5. नीचे "टेस्ट लेबल प्रिंट करें" क्लिक करें। यदि QZ Tray अनुमति माँगे, तो Allow क्लिक करें — प्रमाणपत्र इंस्टॉल होने पर यह दोबारा नहीं पूछेगा।',
'QZ_Step_Save' => '6. ये सेटिंग्स सहेजने के लिए Submit क्लिक करें। अब बारकोड प्रिंट पेज के लेबल ब्राउज़र के प्रिंट डायलॉग के बिना सीधे इस प्रिंटर पर प्रिंट होंगे।',
'QZ_Setup_Note' => 'QZ Tray उसी कंप्यूटर पर चलता है जिससे आप ब्राउज़ कर रहे हैं, इसलिए Stocky के रिमोट सर्वर पर होस्ट होने पर भी यह काम करता है। लेबल प्रिंट करने वाले हर कंप्यूटर पर QZ Tray इंस्टॉल होना चाहिए।',

// PWA settings tab — installable app identity
'PWA_Enabled' => 'इंस्टॉल करने योग्य ऐप सक्षम करें',
'PWA_Enabled_Help' => 'ब्राउज़र को फ़ोन, टैबलेट और डेस्कटॉप पर यह ऐप इंस्टॉल करने का सुझाव देने देता है, और ऑफ़लाइन पेज कैश में रखता है। बंद करने पर इंस्टॉल का सुझाव हर जगह से हट जाता है और अगली विज़िट पर कैश साफ़ हो जाता है।',
'PWA_Identity' => 'ऐप की पहचान',
'PWA_Launch' => 'लॉन्च और दिखावट',
'PWA_App_Name' => 'ऐप का नाम',
'PWA_App_Name_Help' => 'इंस्टॉल सुझाव और ऐप सूची में दिखता है। Appearance सेटिंग्स का ऐप नाम उपयोग करने के लिए खाली छोड़ें।',
'PWA_Short_Name' => 'छोटा नाम',
'PWA_Short_Name_Help' => 'होम स्क्रीन पर आइकन के नीचे दिखता है, जहाँ लंबे नाम कट जाते हैं। ऐप नाम में "|" से पहले का हिस्सा उपयोग करने के लिए खाली छोड़ें।',
'PWA_Description' => 'विवरण',
'PWA_Description_Help' => 'कुछ ऐप स्टोर और इंस्टॉल डायलॉग में दिखता है।',
'PWA_Start_Url' => 'लॉन्च पेज',
'PWA_Start_Url_Help' => 'इंस्टॉल किया गया ऐप जिस पेज पर खुलता है, "/" से शुरू होने वाले पाथ के रूप में। सीधे POS में खोलने के लिए /next/pos उपयोग करें।',
'PWA_Display_Mode' => 'डिस्प्ले मोड',
'PWA_Display_Mode_Help' => 'standalone ब्राउज़र बार छिपाता है; fullscreen स्टेटस बार भी छिपाता है; browser सामान्य टैब खोलता है।',
'PWA_Orientation' => 'ओरिएंटेशन',
'PWA_Theme_Color' => 'थीम रंग',
'PWA_Theme_Color_Help' => 'इंस्टॉल किए गए ऐप के आसपास के सिस्टम बार को रंग देता है।',
'PWA_Background_Color' => 'स्प्लैश बैकग्राउंड',
'PWA_Background_Color_Help' => 'ऐप शुरू होते समय दिखने वाली स्प्लैश स्क्रीन का बैकग्राउंड।',
'PWA_Preview' => 'पूर्वावलोकन',
'PWA_View_Manifest' => 'मैनिफ़ेस्ट फ़ाइल देखें',
'PWA_Reinstall_Notice' => 'जिन डिवाइसों पर ऐप पहले से इंस्टॉल है, वे अनइंस्टॉल करके दोबारा इंस्टॉल करने तक पुराना नाम और आइकन रखते हैं।',

'Label_Render_Mode' => 'लेबल रेंडरिंग',
'Label_Render_Mode_Hint' => 'लेबल कैसे बनाया जाए। प्रिंटर फ़ॉन्ट सबसे तेज़ है और सबसे स्पष्ट बारकोड देता है, लेकिन केवल बुनियादी लैटिन अक्षर प्रिंटर के अपने टाइपफ़ेस में प्रिंट करता है। पूर्वावलोकन छवि आपके लेबल डिज़ाइन को हूबहू दोहराती है — आपका चुना फ़ॉन्ट, कोई भी भाषा — जैसे विशेष लेबल सॉफ़्टवेयर करते हैं।',
'Render_Native' => 'प्रिंटर फ़ॉन्ट (सबसे तेज़)',
'Render_Raster' => 'पूर्वावलोकन छवि (हूबहू डिज़ाइन)',
'Label_Width_Mm' => 'लेबल की चौड़ाई (मिमी)',
'Label_Height_Mm' => 'लेबल की ऊँचाई (मिमी)',
'Label_Size_Hint' => 'रोल पर एक स्टिकर का वास्तविक आकार। यह लोड किए गए लेबल से बिल्कुल मेल खाना चाहिए — गलत आकार से प्रिंटर गैप को गलत जगह खोजता है, जिससे हर लेबल और आगे खिसककर प्रिंट होता है।',
'Calibrate_Labels' => 'लेबल कैलिब्रेट करें',
'Calibrate_Labels_Hint' => 'प्रिंटर स्टिकर और गैप मापने के लिए कुछ लेबल आगे बढ़ाता है। नया रोल लोड करने के बाद एक बार चलाएँ, या जब प्रिंट की स्थिति खिसकने लगे।',
'Calibration_Sent' => 'कैलिब्रेशन शुरू हुआ — प्रिंटर मापने के लिए कुछ खाली लेबल आगे बढ़ाएगा। रुकने पर एक टेस्ट प्रिंट करें।',
'Label_Printer_Dpi' => 'प्रिंटहेड रिज़ॉल्यूशन',
'Label_Printer_Dpi_Hint' => 'अधिकांश लेबल प्रिंटर 203 dpi के होते हैं। पक्का नहीं? नीचे "रिज़ॉल्यूशन पता करें" बटन उपयोग करें — यह उत्तर प्रिंट कर देता है।',
'Find_Resolution' => 'रिज़ॉल्यूशन पता करें',
'Find_Resolution_Hint' => '203 और 300 चिह्नित दो लेबल प्रिंट करता है। सही वाले में स्टिकर पर चारों ओर छोटे समान हाशिये के साथ पूरा आयत दिखता है; गलत वाले में किनारे गायब होते हैं या वह अगले स्टिकर पर चला जाता है।',
'Dpi_Test_Sent' => '203 और 300 चिह्नित दो लेबल प्रिंट हो रहे हैं। सही वाले में चारों ओर छोटे समान हाशिये के साथ पूरा आयत दिखता है — "प्रिंटहेड रिज़ॉल्यूशन" उसी संख्या पर सेट करके सहेजें।',
'Label_Offset_X' => 'क्षैतिज ऑफ़सेट (मिमी)',
'Label_Offset_X_Hint' => 'प्रिंट को स्टिकर पर बगल में खिसकाता है। जब टेक्स्ट एक किनारे पर कट रहा हो तब उपयोग करें — जैसे 2.5, जब सफ़ेद स्टिकर चौड़े बैकिंग पेपर के बीच में हो। 0.5 के चरणों में समायोजित करें।',
'Label_Offset_Y' => 'लंबवत ऑफ़सेट (मिमी)',
'Label_Offset_Y_Hint' => 'प्रिंट को लेबल की लंबाई में खिसकाता है। डिज़ाइन का ऊपरी हिस्सा कटे या गायब हो तो बढ़ाएँ; बहुत नीचे से शुरू हो तो घटाएँ।',
'Feed_To_Tear' => 'टियर एज तक फ़ीड करें',
'Feed_To_Tear_Hint' => 'हर काम के बाद लेबल को टियर बार तक आगे बढ़ाता है। यदि लेबल नीचे खिसककर प्रिंट हों या दो स्टिकरों में बँट जाएँ तो बंद रखें — कई प्रिंटर अगले लेबल से पहले पीछे नहीं लौटते।',
'Install_App' => 'ऐप इंस्टॉल करें',
'pos.Cart_Restored' => 'आपका कार्ट पुनर्स्थापित हो गया',
'pos.Draft_Saved_Offline' => 'ड्राफ़्ट ऑफ़लाइन सहेजा गया। ऑनलाइन आने पर सिंक हो जाएगा।',
'pos.Client_Saved_Offline' => 'ग्राहक ऑफ़लाइन सहेजा गया। ऑनलाइन आने पर सिंक हो जाएगा।',
'Mobile_App_Settings' => 'मोबाइल ऐप',
'Mobile_App_Settings_Help' => 'Stocky मोबाइल ऐप नियंत्रित करें: इसे चालू या बंद करें, नाम, लोगो और रंग तय करें, और चुनें कि आपकी टीम कौन से मॉड्यूल देखे।',
'Mobile_App_Enabled' => 'मोबाइल ऐप सक्षम',
'Mobile_App_Enabled_Help' => 'बंद होने पर मोबाइल ऐप से कोई साइन इन नहीं कर सकता और उसकी जगह नीचे दिया संदेश दिखता है।',
'Mobile_App_Disabled_Notice' => 'मोबाइल ऐप फ़िलहाल बंद है।',
'Mobile_Maintenance_Message' => 'उपयोगकर्ताओं को दिखाया जाने वाला संदेश',
'Mobile_Maintenance_Message_Help' => 'बताएँ कि ऐप क्यों उपलब्ध नहीं है और कब वापस आएगा।',
'Mobile_Branding' => 'ब्रांडिंग',
'Mobile_App_Name' => 'ऐप का नाम',
'Mobile_App_Name_Help' => 'साइन-इन स्क्रीन और ऐप के ऊपर दिखता है। कंपनी का नाम उपयोग करने के लिए खाली छोड़ें।',
'Mobile_Logo' => 'ऐप लोगो',
'Mobile_Logo_Help' => 'वर्गाकार छवि, कम से कम 512x512। मुख्य लोगो उपयोग करने के लिए खाली छोड़ें।',
