'Mobile_Primary_Color' => 'मुख्य रंग',
'Mobile_Primary_Color_Help' => 'ऐप में बटन, POS बटन और हाइलाइट के लिए उपयोग होता है।',
'Mobile_Theme_Mode' => 'डिफ़ॉल्ट थीम',
'Mobile_Theme_Mode_Help' => 'नए डिवाइस जिससे शुरू करते हैं। उपयोगकर्ता इसे ऐप में बदल सकते हैं।',
'Mobile_Features' => 'सुविधाएँ',
