'Wholesale_Pricing_Variants_Hint' => 'एक ही सीढ़ी पूरे उत्पाद पर लागू होती है: हर वैरिएंट अपनी लाइन के किसी स्तर तक पहुँचने पर उस स्तर के मूल्य पर बिकता है।',
