/* ---- Online orders guide (Store > Online Orders) ---- */
'Orders_Guide' => 'ऑर्डर गाइड',
'Ord_Guide_Intro' => 'आपके ऑनलाइन स्टोर पर दिया गया ऑर्डर आपके स्टॉक और खातों तक कैसे पहुँचता है, और पैसा वास्तव में कहाँ दर्ज होता है।',
'Ord_Guide_Lifecycle_Title' => 'ऑर्डर स्थिति',
'Ord_Guide_Lifecycle_Pending' => 'आपकी समीक्षा की प्रतीक्षा में नया ऑर्डर। केवल लंबित ऑर्डर ही पुष्ट या रद्द किया जा सकता है।',
'Ord_Guide_Lifecycle_Confirmed' => 'आपने ऑर्डर स्वीकार किया। Stocky आपके चुने गोदाम में एक बिक्री बनाता है और स्टॉक घटाता है — वही बिक्री वह रिकॉर्ड है जिससे आपकी स्टॉक, भुगतान और लाभ रिपोर्ट पढ़ी जाती हैं।',
'Ord_Guide_Lifecycle_Shipped' => 'आपने ऑर्डर भेज दिया। केवल पूर्ति का चरण: स्टॉक पुष्टि के समय ही घट चुका था।',
'Ord_Guide_Lifecycle_Delivered' => 'ग्राहक को ऑर्डर मिल गया। इसी से वापसी की अवधि शुरू होती है।',
'Ord_Guide_Lifecycle_Cancelled' => 'ऑर्डर पुष्टि से पहले छोड़ दिया गया, इसलिए न कोई बिक्री बनी और न स्टॉक घटा।',
'Ord_Guide_PaymentStatus_Tip' => 'चेकआउट पर सेट होता है और यहाँ संपादन योग्य नहीं। भुगतान दर्ज करने का तरीका देखने के लिए क्लिक करें।',
'Ord_Guide_Payment_Title' => 'भुगतान स्थिति',
'Ord_Guide_Payment_Intro' => 'यह कॉलम दर्ज करता है कि ग्राहक ने चेकआउट पर कैसे भुगतान करना चुना। इसे स्टोरफ़्रंट सेट करता है और इस पेज से संपादित नहीं किया जा सकता — पैसा स्वयं उस बिक्री पर ट्रैक होता है जो ऑर्डर की पुष्टि से बनती है।',
'Ord_Guide_Payment_Paid' => 'ग्राहक ने पेमेंट गेटवे के माध्यम से ऑनलाइन भुगतान पहले ही कर दिया। ऑर्डर की पुष्टि करने पर बिक्री Paid के रूप में बनती है और भुगतान आपके लिए दर्ज हो जाता है — और कुछ करने की ज़रूरत नहीं।',
'Ord_Guide_Payment_Pending' => 'कैश ऑन डिलीवरी, बैंक ट्रांसफ़र या कोई अन्य बाद में भुगतान की विधि। ऑर्डर की पुष्टि करने पर बिक्री Unpaid के रूप में बनती है, इसलिए पैसा मिलने पर आप उसे स्वयं दर्ज करते हैं — नीचे के चरण देखें।',
'Ord_Guide_Payment_Failed' => 'गेटवे ने भुगतान अस्वीकार किया या ग्राहक ने उसे बीच में छोड़ दिया। ऑर्डर स्वचालित रूप से रद्द हो जाता है।',
'Ord_Guide_MarkPaid_Title' => 'भुगतान को pending से paid में बदलना',
'Ord_Guide_MarkPaid_Step1' => 'पहले यहाँ ऑर्डर की पुष्टि करें — पुष्टि से ही बिक्री बनती है।',
'Ord_Guide_MarkPaid_Step2' => 'Sales > All Sales खोलें और वह बिक्री खोजें (वही ग्राहक, और विवरण पेज पर उस ऑनलाइन ऑर्डर का उल्लेख होता है जिससे यह बनी)।',
'Ord_Guide_MarkPaid_Step3' => 'पंक्ति के एक्शन मेनू से Create Payment चुनें।',
'Ord_Guide_MarkPaid_Step4' => 'राशि, भुगतान विधि और तिथि दर्ज करके सहेजें। राशि के अनुसार बिक्री अपने आप Partial या Paid हो जाती है।',
'Ord_Guide_MarkPaid_Note' => 'यहाँ दिखाई गई भुगतान स्थिति चेकआउट के चुनाव को दर्ज करती रहती है और जैसी है वैसी रहती है। बिक्री ही लेखा रिकॉर्ड है, और वही आपकी भुगतान और लाभ रिपोर्ट में जाती है। अपनी दर्ज की गई जानकारी देखने या संपादित करने के लिए बिक्री पर Show Payments उपयोग करें।',
'Ord_Guide_Notes_Title' => 'जानने योग्य बातें',
'Ord_Guide_Note_Warehouse' => 'पुष्टि करते समय चुना गया गोदाम तय करता है कि स्टॉक कहाँ से लिया जाएगा। जो गोदाम पूरा ऑर्डर पूरा नहीं कर सकते, वे उस सूची में Out of Stock चिह्नित होते हैं।',
'Ord_Guide_Note_Preorder' => 'प्री-ऑर्डर वस्तुएँ स्टॉक जाँच छोड़ देती हैं, इसलिए उन्हें शामिल करने वाला ऑर्डर मात्रा उपलब्ध न होने पर भी पुष्ट किया जा सकता है।',
'Ord_Guide_Note_Flagged' => 'Flagged टैग का अर्थ है कि ऑर्डर चेकआउट पर धोखाधड़ी जाँच में पकड़ा गया। कारण देखने के लिए टैग पर होवर करें और पुष्टि से पहले ऑर्डर की समीक्षा करें।',
'Ord_Guide_Note_Cancel' => 'रद्द करना केवल तभी संभव है जब ऑर्डर लंबित हो। पुष्टि के बाद इसे बिक्री या ग्राहक वापसी के माध्यम से उलटें।',


