'VG_Opt_Step2' => 'रंग या आकार जैसा विकल्प नाम टाइप करें, या सुझावों में से कोई एक चुनें।',
'VG_Opt_Step3' => 'एक मान टाइप करें (उदाहरण के लिए लाल) और Enter दबाएँ। हर मान के लिए दोहराएँ; अल्पविराम से भी मान अलग होते हैं। किसी मान को हटाने के लिए उस पर x क्लिक करें।',
