'VG_Opt_Step5' => '"वेरिएंट जनरेट करें" पर क्लिक करें। हर संयोजन के लिए एक पंक्ति बनती है और उसका नाम स्वचालित रूप से बनता है, उदाहरण के लिए "Red / S"।',
'VG_Opt_Step6' => 'हर पंक्ति पर लागत और मूल्य दर्ज करें, या "सभी पर लागू करें" में एक मान टाइप करें और उसे हर पंक्ति में कॉपी करने के लिए लागत या मूल्य पर क्लिक करें।',
'VG_Opt_Step7' => 'कोड आपके लिए जनरेट किए जाते हैं। अपना कोड टाइप करें या दूसरा जनरेट करने के लिए रीफ़्रेश आइकन पर क्लिक करें।',
'VG_Opt_Step8' => 'वैकल्पिक: किसी विकल्प पर "रंग स्वैच" चुनें और हर मान के लिए एक रंग चुनें; स्टोर इसे रंगीन बिंदु के रूप में दिखाता है।',
'VG_Rows_Title' => 'वेरिएंट पंक्तियाँ',
'VG_Rows_Text' => 'हर पंक्ति में छवि, कोड, बारकोड, लागत, मूल्य, थोक मूल्य और न्यूनतम बिक्री मूल्य होता है। उत्पाद बनाते समय आप हर वेरिएंट के लिए प्रति गोदाम प्रारंभिक स्टॉक भी दर्ज कर सकते हैं। "अपूर्ण" टैग का अर्थ है कि पंक्ति में किसी एक विकल्प का मान नहीं है।',
'VG_List_Title' => 'सरल सूची मोड',
'VG_List_Text' => 'एक वेरिएंट नाम टाइप करें और पंक्ति जोड़ने के लिए Enter दबाएँ (या जोड़ें पर क्लिक करें), फिर उसका कोड और मूल्य भरें। यह पारंपरिक तरीका है और मौजूदा उत्पादों के लिए उपलब्ध रहता है।',
'VG_Edit_Title' => 'बाद में संपादन',
'VG_Edit_1' => 'एक मान जोड़ें और "वेरिएंट जनरेट करें" पर क्लिक करें: केवल गायब संयोजन जोड़े जाते हैं। मौजूदा पंक्तियाँ अपने कोड, मूल्य और इतिहास बनाए रखती हैं।',
'VG_Edit_2' => 'किसी मान या विकल्प को हटाने से उसका उपयोग करने वाली पंक्तियाँ हट जाती हैं। पहले से सहेजी गई पंक्तियाँ पुष्टि के बाद, उत्पाद सहेजने पर डिलीट होती हैं।',
'VG_Edit_3' => 'जिस वेरिएंट में अभी भी स्टॉक है उसे हटाया नहीं जा सकता। पहले उसके स्टॉक का समायोजन या स्थानांतरण करें।',
'VG_Edit_4' => '"सरल सूची" पर स्विच करने से पंक्तियाँ और उनके नाम रहते हैं, लेकिन विकल्प परिभाषाएँ हट जाती हैं।',
'VG_Store_Title' => 'ऑनलाइन स्टोर पर',
'VG_Store_Text' => 'ग्राहक प्रत्येक विकल्प के लिए एक मान चुनते हैं, उदाहरण के लिए पहले रंग फिर आकार। जो संयोजन मौजूद नहीं हैं वे अक्षम रहते हैं और स्टॉक में न होने वाले काट दिए जाते हैं। चुना गया वेरिएंट ही कार्ट में जाता है।',
'Choose_Source' => 'स्रोत चुनें',
'Portal_Request' => 'पोर्टल अनुरोध',
'Portal_Quotation_Requests' => 'पोर्टल कोटेशन अनुरोध',
'Warehouse_Invoice_Address_Help' => 'इस गोदाम द्वारा जारी इनवॉइस पर छपने वाला पता। सेटिंग्स से कंपनी का पता उपयोग करने के लिए खाली छोड़ें।',
'Warehouse_Logo_Help' => 'इस गोदाम के इनवॉइस और POS रसीदों पर छपने वाला लोगो। कंपनी लोगो उपयोग करने के लिए खाली छोड़ें।',
'Warehouse_Invoice_Footer_Help' => 'इस गोदाम द्वारा जारी इनवॉइस के नीचे छपने वाला अतिरिक्त नोट।',
'Issued_By' => 'जारीकर्ता',
'Enable_Warehouse_Letterhead' => 'इनवॉइस पर गोदाम लेटरहेड',
'Enable_Warehouse_Letterhead_Hint' => 'इनवॉइस, POS रसीदों और सार्वजनिक इनवॉइस पेज पर जारी करने वाला गोदाम प्रिंट करें: इसका नाम कंपनी के नाम की जगह लेता है, और इसका पता, फ़ोन, ईमेल, लोगो और फ़ुटर नोट कंपनी वालों की जगह लेते हैं। गोदाम पर खाली छोड़ा गया कोई भी फ़ील्ड वैश्विक कंपनी सेटिंग्स से लिया जाता है।',
'Warehouse_Letterhead_Receipt_Notice' => 'गोदाम लेटरहेड चालू है: वास्तविक रसीद पर छपा स्टोर का नाम, पता और फ़ोन उस गोदाम से आता है जिसने बिक्री जारी की, और इसका फ़ुटर नोट ग्राहक नोट के नीचे जोड़ा जाता है।',
'Warehouse_Letterhead_Receipt_Demo' => 'शाखा फ़ुटर नोट — "गोदाम" पेज में प्रत्येक गोदाम के लिए सेट करें।',
