'Upd_Manual_Step_Done' => 'हो गया! अपडेट किए गए एप्लिकेशन का आनंद लें।',
'Upd_Note_Blank_Pages' => 'नोट: यदि कोई पृष्ठ लोड नहीं हो रहा या खाली है, तो सुनिश्चित करें कि आपने अपने ब्राउज़र का कैश साफ़ कर दिया है।',
'Upd_Guide_Before_Title' => '1. अपडेट करने से पहले',
'Upd_Guide_Before_Download' => 'अपने CodeCanyon खाते ({path}) से एप्लिकेशन का {package} डाउनलोड करें। इसे एक्सट्रैक्ट न करें — अपडेटर को ZIP ठीक वैसे ही चाहिए जैसा डाउनलोड हुआ है।',
'Upd_Latest_Full_Zip' => 'नवीनतम पूर्ण ZIP पैकेज',
