'Upd_Guide_Before_Quiet' => 'शांत समय चुनें: अपडेट के दौरान एप्लिकेशन थोड़े समय के लिए रखरखाव मोड में चला जाता है और अन्य उपयोगकर्ता लॉक हो जाते हैं।',
'Upd_Guide_Before_No_Manual' => 'आपको मैन्युअल रूप से बैकअप लेने, फ़ाइलें एक्सट्रैक्ट करने, कमांड चलाने, कॉन्फ़िगरेशन फ़ाइलें संपादित करने या डेटाबेस को छूने की आवश्यकता {not} है — अपडेटर यह सब अपने आप करता है। (बेशक, एक अतिरिक्त मैन्युअल बैकअप कभी नुकसान नहीं करता।)',
'Upd_Not' => 'नहीं',
'Upd_Guide_Code_Overwritten' => 'यदि आपने एप्लिकेशन कोड को मैन्युअल रूप से संशोधित किया है, तो अपडेट आपके परिवर्तनों को ओवरराइट कर देगा। आपका डेटा, अपलोड, सेटिंग्स और .env हमेशा सुरक्षित रहते हैं।',
'Upd_Guide_Running_Title' => '2. अपडेट चलाना',
'Upd_Guide_Run_Open' => '{path} (यह पृष्ठ) खोलें और {tab} टैब पर बने रहें।',
'Upd_Guide_Run_Upload' => '{upload}: डाउनलोड किए गए पैकेज को अपलोड बॉक्स में क्लिक करके चुनें या खींचकर छोड़ें। बड़ी फ़ाइलें छोटे-छोटे हिस्सों में अपलोड होती हैं, इसलिए यह कम अपलोड सीमा वाली साझा होस्टिंग पर भी काम करता है। एक चेकसम दूषित या अधूरे अपलोड से सुरक्षा करता है।',
'Upd_Upload_The_Zip' => 'ZIP अपलोड करें',
'Upd_Guide_Run_Validation' => 'अपलोड के बाद {auto} (आप इसे {button} बटन से फिर से चला सकते हैं)। सिस्टम जाँचता है: ZIP अखंडता, पैकेज संरचना और पूर्णता, संस्करण संगतता (डाउनग्रेड अस्वीकार किए जाते हैं), आवश्यक PHP संस्करण और एक्सटेंशन, फ़ाइल अनुमतियाँ, खाली डिस्क स्थान, डेटाबेस कनेक्शन, कॉन्फ़िगरेशन, और यह कि कोई अन्य अपडेट नहीं चल रहा है।',
'Upd_Validation_Runs_Automatically' => 'सत्यापन अपने आप चलता है',
'Upd_Guide_Run_Review' => '{panel} पैनल की समीक्षा करें। {button} बटन केवल तभी दिखाई देता है जब हर महत्वपूर्ण जाँच सफल हो। यदि कोई जाँच विफल होती है, तो संदेश आपको ठीक-ठीक बताता है कि क्या ठीक करना है।',
'Upd_Guide_Run_Click' => '{button} पर क्लिक करें और पुष्टि करें। फिर बस {keep} और प्रगति पट्टी देखें। सिस्टम क्रम से ये कार्य करता है:',
'Upd_Keep_Page_Open' => 'इस पृष्ठ को खुला रखें',
'Upd_Guide_Phase_Backup' => '{label} — पूर्ण डेटाबेस डंप, अपडेट द्वारा बदली जा सकने वाली हर एप्लिकेशन फ़ाइल का ZIP, और {env} की एक प्रति बनाई जाती है और {verified} की जाती है। आपके अपलोड ({images}) और {storage} को अपडेट कभी नहीं छूता, इसलिए उन्हें संग्रहित नहीं किया जाता। यदि बैकअप नहीं बन पाता, तो अपडेट यहीं रुक जाता है और कुछ भी नहीं बदला जाता।',
'Upd_Verified' => 'सत्यापित',
'Upd_Guide_Phase_Prepare' => '{label} — नया संस्करण एक स्टेजिंग क्षेत्र में एक्सट्रैक्ट किया जाता है और फिर से सत्यापित किया जाता है। लाइव एप्लिकेशन अभी भी अछूता रहता है।',
'Upd_Guide_Phase_Maintenance' => '{label} — रखरखाव मोड सक्षम किया जाता है; आगंतुकों को एक अनुकूल "हम जल्द ही वापस आएँगे" स्क्रीन दिखाई देती है।',
'Upd_Guide_Phase_Files' => '{label} — नई फ़ाइलें लगभग तुरंत बदल दी जाती हैं; पुरानी फ़ाइलें रोलबैक के लिए अलग रखी जाती हैं। संरक्षित पाथ ({env}, {storage}, {images}) कभी नहीं बदले जाते।',
'Upd_Guide_Phase_Database' => '{label} — माइग्रेशन चलते हैं, फिर अनुमतियाँ, अनुवाद और टेम्पलेट रीफ़्रेश किए जाते हैं।',
'Upd_Guide_Phase_Cache' => '{label} — सभी कैश साफ़ करके फिर से बनाए जाते हैं।',
'Upd_Guide_Phase_Verify' => '{label} — हेल्थ जाँचें पुष्टि करती हैं कि नया संस्करण शुरू होता है, डेटाबेस काम करता है, सभी माइग्रेशन चले हैं, और कॉन्फ़िगरेशन मान्य है।',
'Upd_Guide_Phase_Done' => '{label} — रखरखाव मोड हटा दिया जाता है और अस्थायी फ़ाइलें साफ़ कर दी जाती हैं।',
'Upd_Guide_Run_Success' => 'जब आपको {success} दिखे, तो {reload} पर क्लिक करें और अपने ब्राउज़र को हार्ड-रीफ़्रेश करें ({keys}) ताकि नए एडमिन पैनल एसेट लोड हों।',
'Upd_Update_Successful_Short' => 'अपडेट सफल',
'Upd_Guide_No_Internet' => 'अपडेट के दौरान इंटरनेट कनेक्शन की आवश्यकता नहीं है — सब कुछ अपलोड किए गए ZIP से आता है। कनेक्शन टूटने या ब्राउज़र बंद करने से अपडेट खराब नहीं होता: सर्वर को ठीक-ठीक याद रहता है कि वह कहाँ रुका था।',
'Upd_Guide_Wrong_Title' => '3. यदि कुछ गलत हो जाए',
'Upd_Guide_Wrong_Rollback' => '{label} — यदि फ़ाइलें बदलना शुरू होने के बाद कुछ भी विफल होता है (एक्सट्रैक्शन त्रुटि, माइग्रेशन विफलता, विफल हेल्थ जाँच, डिस्क भर जाना, …), तो सिस्टम अपने आप सत्यापित बैकअप से पिछली फ़ाइलें और डेटाबेस पुनर्स्थापित करता है, रखरखाव मोड हटाता है, और {message} रिपोर्ट करता है। आप ठीक वहीं पहुँच जाते हैं जहाँ से शुरू किया था।',
'Upd_Automatic_Rollback' => 'स्वचालित रोलबैक',
'Upd_Failed_Previous_Restored' => 'अपडेट विफल — पिछला संस्करण पुनर्स्थापित किया गया',
'Upd_Guide_Wrong_Interrupted' => '{label} (सर्वर रीस्टार्ट, टाइमआउट, बंद ब्राउज़र, बिजली गुल) — जब आप यह पृष्ठ फिर से खोलते हैं, तो एक लाल बैनर दो सुरक्षित विकल्प देता है: {resume} (ठीक उसी चरण से फिर शुरू होता है जहाँ रुका था) या {rollback} (बैकअप से पिछला संस्करण पुनर्स्थापित करता है)।',
'Upd_Interrupted_Update' => 'बाधित अपडेट',
'Upd_Guide_Wrong_Unreachable' => '{label} — {path} पर स्टैंडअलोन {console} का उपयोग करें। यह तब भी काम करता है जब साइट रखरखाव मोड में हो या एडमिन पैनल एसेट खराब हों, और वही जारी रखें / रोलबैक करें कार्रवाइयाँ प्रदान करता है। रखरखाव स्क्रीन के नीचे एक अलग "व्यवस्थापक पहुँच" लिंक भी है।',
'Upd_Admin_Unreachable' => 'एडमिन पैनल तक पहुँच नहीं',
'Upd_Recovery_Console' => 'रिकवरी कंसोल',
'Upd_Guide_Wrong_Locked_Out' => '{label} — अपडेट चलने के दौरान, यह पृष्ठ एक {link} दिखाता है। यदि आपको वापस आने की आवश्यकता हो (उदाहरण के लिए सत्र समाप्त होने के बाद) तो इसे सहेज लें; यह आपको रखरखाव स्क्रीन से आगे जाने देता है ताकि आप फिर से लॉग इन कर सकें।',
'Upd_Locked_Out_Maintenance' => 'रखरखाव मोड के कारण लॉक',
'Upd_Bypass_Link' => 'बायपास लिंक',
'Upd_Guide_Wrong_Concurrent' => '{label} — उन्हें {message} दिखाई देगा। एक समय में केवल एक ही अपडेट चल सकता है।',
'Upd_Another_Admin_Updating' => 'कोई अन्य एडमिन उसी समय अपडेट करने का प्रयास करता है',
'Upd_Guide_Backups_Title' => '4. बैकअप और पुनर्स्थापना',
'Upd_Guide_Backups_Created' => 'हर अपडेट कुछ भी छूने से {before} एक बैकअप बनाता है: अपडेट द्वारा बदली जा सकने वाली सभी एप्लिकेशन फ़ाइलें, {env} की एक प्रति, और पूर्ण डेटाबेस डंप। अपलोड और {storage} को अपडेट कभी संशोधित नहीं करता, इसलिए वे इसका हिस्सा नहीं हैं — उनके अपने बैकअप रखें। बैकअप {path} में रहते हैं और वेब से कभी उपलब्ध नहीं होते।',
'Upd_Before' => 'पहले',
'Upd_Guide_Backups_Panel' => '{tab} टैब पर {panel} पैनल उन्हें तिथि, संस्करण और आकार के साथ सूचीबद्ध करता है। वहाँ से आप किसी भी पूर्ण बैकअप को {restore} कर सकते हैं (फ़ाइलें + डेटाबेस — पहले वर्तमान डेटाबेस की एक सुरक्षा प्रति ली जाती है) या पुराने बैकअप {delete} कर सकते हैं।',
'Upd_Restore_Verb' => 'पुनर्स्थापित',
'Upd_Delete_Verb' => 'डिलीट',
'Upd_Guide_Backups_Retention' => 'कितने बैकअप रखे जाएँ, यह चुनने के लिए {keep} का उपयोग करें; हर सफल अपडेट के बाद पुराने बैकअप अपने आप हटा दिए जाते हैं। बचा हुआ एकमात्र पूर्ण बैकअप कभी हटाया नहीं जा सकता — वापस लौटने का रास्ता हमेशा आपके पास रहता है।',
'Upd_Guide_Manual_Title' => '5. मैन्युअल अपडेट (वैकल्पिक तरीका)',
'Upd_Guide_Manual_Text' => 'यदि आप हाथ से अपडेट करना पसंद करते हैं, या आपके सर्वर पर अपलोडर का उपयोग नहीं हो सकता, तो इस पेज के {tab} टैब पर दिए गए चरण-दर-चरण निर्देशों का पालन करें।',
'Upd_Guide_Clear_Cache_First' => 'यदि किसी भी अपडेट के बाद पेज टूटे हुए या खाली दिखें, तो पहले अपने ब्राउज़र का कैश साफ़ करें — लगभग हमेशा यही कारण होता है।',
'Upd_Restore_Backup_Confirm' => 'यह बैकअप पुनर्स्थापित करें? मौजूदा फ़ाइलें और मौजूदा डेटाबेस बैकअप से बदल दिए जाएँगे। पहले मौजूदा डेटाबेस की एक सुरक्षा प्रति ली जाती है। (v{version} — {date})',
'Woo_Guide_Lead' => 'WooCommerce शॉप ERP के साथ कैसे तालमेल में रहती है। नीचे दी गई cron लाइनें इसी सर्वर के लिए बनी हैं, इसलिए इन्हें सीधे इस पर कॉपी किया जा सकता है।',
'Woo_Guide_Ways_Note' => 'Shopify के विपरीत, WooCommerce अपने आप ERP को कुछ नहीं भेजता — यहाँ कोई Webhook रिसीवर नहीं है, इसलिए {in} आने वाला सब कुछ शेड्यूल पर आता है। केवल {out} जाने वाला स्टॉक तुरंत जा सकता है।',
'Woo_In' => 'अंदर',
'Woo_Out' => 'बाहर',
'Woo_Guide_Both_Ways_Title' => 'दोनों तरीकों के लिए पहले यह ज़रूरी है',
'Woo_Api_Keys' => 'API कुंजियाँ',
'Woo_Guide_Api_Keys_Text' => '{path}, अनुमति {perm}। कंज़्यूमर कुंजी और सीक्रेट को स्टोर URL के साथ {settings} टैब में कॉपी करें — आपकी साइट का पता, अंत में स्लैश के बिना, जैसे {example}।',
'Woo_Credentials_Saved' => 'क्रेडेंशियल सहेजे गए',
'Woo_Not_Configured_Yet' => 'अभी कॉन्फ़िगर नहीं किया गया',
'Woo_Guide_Wp_App_Password_Title' => 'WordPress एप्लिकेशन पासवर्ड (वैकल्पिक)',
'Woo_Guide_Wp_App_Password_Text' => 'केवल उत्पाद छवियों के लिए उपयोग होता है। WooCommerce API उत्पाद, स्टॉक, श्रेणियाँ, ब्रांड, ग्राहक और ऑर्डर स्थानांतरित करता है; WordPress API मीडिया लाइब्रेरी में खोज करता है और वह छवि अपलोड करता है जो अभी वहाँ नहीं है।',
'Woo_Guide_Wp_App_Password_Note' => 'ऐसे WordPress उपयोगकर्ता का उपयोग करें जो मीडिया प्रबंधित कर सकता हो, और पासवर्ड {path} के अंतर्गत बनाएँ। दोनों फ़ील्ड खाली छोड़ने पर भी सब कुछ सिंक होता है — केवल छवि जोड़ना छोड़ दिया जाता है।',
'Woo_Guide_Pick_Way_Title' => 'फिर चुनें कि यह तालमेल कैसे बनाए रखे',
'Woo_Right_Away' => 'तुरंत',
'Woo_Stock_Live' => 'स्टॉक लाइव',
'Woo_Stock_Not_Live' => 'स्टॉक लाइव नहीं',
'Woo_Guide_Realtime_Lead' => 'केवल एक दिशा: ERP से बाहर जाने वाला स्टॉक और उत्पाद। WooCommerce में किए गए ऑर्डर और उत्पाद संपादन अब भी शेड्यूल पर ही आते हैं — दूसरा टैब देखें।',
'Woo_Push_Stock_On_Change' => 'स्टॉक बदलते ही पुश करें',
'Woo_Setting_People_Miss' => 'यही वह सेटिंग है जिसे लोग अक्सर चूक जाते हैं',
'Woo_Guide_Pos_Sale_Not_Reach' => 'POS बिक्री अपने आप WooCommerce तक {not} पहुँचती। इसे बंद छोड़ने पर शॉप को अगले स्टॉक सिंक पर ही पता चलता है — डिफ़ॉल्ट रूप से एक घंटा — और उस अवधि में वह ऐसी इकाई बेच सकती है जिसे आप काउंटर पर पहले ही बेच चुके हैं।',
'Woo_Does_Not' => 'नहीं',
'Woo_Guide_Tick_Instant' => '{settings} टैब पर {option} पर टिक करें। बस इतना ही सेटअप है — न कोई वर्कर, न cron। इसके बाद हर बिक्री, वापसी, समायोजन, स्थानांतरण और प्राप्त खरीद बिक्री सहेजे जाने के तुरंत बाद केवल उन्हीं उत्पादों का पुश भेजती है, और बीस लाइनों वाली बिक्री के लिए एक ही पुश लगता है, बीस नहीं। काउंटर को कभी इसकी प्रतीक्षा नहीं करनी पड़ती।',
'Woo_Currently' => 'वर्तमान में:',
'Woo_Instant_On_Text' => 'चालू — बदलाव पर स्टॉक पुश होता है',
'Woo_Instant_Off_Text' => 'बंद — स्टॉक केवल शेड्यूल पर',
'Woo_Guide_Instant_Note' => 'केवल वही उत्पाद पुश होते हैं जो पहले से WooCommerce से लिंक हैं — जो कभी सिंक नहीं हुआ, उसके लिए शॉप में सुधारने को कुछ नहीं है। वेरिएबल उत्पाद अपने पैरेंट के माध्यम से जाते हैं, और कॉम्बो तब फिर से पुश होता है जब उसका कोई भी घटक बदलता है। बल्क ऑपरेशन (उत्पाद हटाना, गोदाम रीसेट करना) बिना कोई इवेंट चलाए स्टॉक लिखते हैं — यह भी एक कारण है कि घंटेवार स्टॉक सिंक भी चालू रखें।',
'Woo_Push_Products_On_Save' => 'उत्पाद सहेजते ही पुश करें',
'Woo_Guide_Tick_Auto_Products' => '{settings} टैब पर {option} पर टिक करें, और Stocky में बनाया, संपादित या डुप्लिकेट किया गया उत्पाद सहेजे जाने के तुरंत बाद WooCommerce को भेजा जाता है — विवरण, मूल्य, वेरिएंट और छवियाँ, फिर उसका स्टॉक। नया उत्पाद रात के उत्पाद सिंक की प्रतीक्षा किए बिना तुरंत शॉप में बन जाता है।',
'Woo_On' => 'चालू',
'Woo_Off' => 'बंद',
'Woo_Guide_Bulk_Imports_Note' => 'बल्क इम्पोर्ट एक-एक करके पुश नहीं होते — इम्पोर्ट के बाद उत्पाद सिंक चलाएँ। पहले श्रेणियाँ और ब्रांड सिंक करें, ताकि पुश किया गया उत्पाद सही श्रेणी में पहुँचे।',
'Woo_Nothing_Else_To_Install' => 'और कुछ इंस्टॉल करने की ज़रूरत नहीं',
'Woo_Guide_Same_Process' => 'न कोई क्यू वर्कर, न cron प्रविष्टि। पुश उसी प्रोसेस में चलता है जिसने बिक्री संभाली थी, रिस्पॉन्स वापस जाने के {after}, इसलिए काउंटर को कभी WooCommerce की प्रतीक्षा नहीं करनी पड़ती। पुश कभी एक-दूसरे पर नहीं चढ़ते: एक पुश चलते समय किए गए बदलाव उसकी प्रतीक्षा करते हैं और उसके तुरंत बाद भेजे जाते हैं।',
'Woo_After' => 'बाद',
'Woo_Guide_Shop_Stops_Answering' => 'जवाब देना बंद करने वाली शॉप को आठ सेकंड बाद छोड़ दिया जाता है, और पुश पाँच मिनट के लिए रुक जाते हैं ताकि हर बिक्री फिर से उसकी प्रतीक्षा न करे; इस बीच आए बदलाव विराम के बाद पहले पुश के साथ भेजे जाते हैं, और घंटेवार स्टॉक सिंक वैसे भी सब पूरा कर लेता है। हर विराम लॉग टैब में दर्ज होता है।',
'Woo_Guide_Artisan_Exception' => 'एक अपवाद: artisan कमांड द्वारा किए गए स्टॉक बदलाव का कोई रिस्पॉन्स नहीं होता जिसके बाद यह चले, इसलिए वह {queue} पर क्यू में डाला जाता है। उन्हें भी तुरंत भेजने के लिए, उस क्यू को प्रोसेस करें:',
'Woo_Cron_Line_Copied' => 'Cron लाइन कॉपी की गई',
'Woo_Command_Copied' => 'कमांड कॉपी की गई',
'Woo_Guide_Not_Woo_Queue' => 'जानबूझकर {queue} क्यू नहीं: वह घंटों चलने वाले कैटलॉग बैच ले जाती है, और उनके पीछे क्यू में डाला गया तत्काल पुश तत्काल नहीं रहेगा।',
'Woo_On_A_Schedule' => 'शेड्यूल पर',
'Woo_Guide_Scheduled_Lead' => 'सब कुछ समय-समय पर दोनों दिशाओं में दोबारा जाँचा जाता है। इसी तरह ऑर्डर ERP तक पहुँचते हैं, कैटलॉग प्रकाशित होता है, और तेज़ रास्ते से छूटी हर चीज़ ठीक होती है। हर जॉब की अपनी cron प्रविष्टि होती है, इसलिए आप केवल वही चलाते हैं जो आप चाहते हैं।',
'Woo_Guide_Sync_Drains_Queue' => '{command} चलते समय अपनी क्यू स्वयं प्रोसेस करता है, इसलिए इन लाइनों के लिए अलग वर्कर की ज़रूरत नहीं है। Windows पर, Task Scheduler का उपयोग करें, प्रोग्राम {program} और वही आर्गुमेंट के साथ, {path} में प्रारंभ करें।',
'Woo_Or_No_Cron' => 'या बिल्कुल भी cron नहीं',
'Woo_Guide_No_Cron_Text' => 'यहाँ का हर टैब माँग पर सिंक करता है, और मैन्युअल सिंक पेज खुला रहने तक अपने बैच स्वयं प्रोसेस करता है — इसलिए छोटी शॉप बिना किसी cron प्रविष्टि के भी चल सकती है। आप वह सब खो देते हैं जो किसी के न देखते समय होता है: ऑर्डर तभी आते हैं जब कोई बटन दबाता है।',
'Woo_Commands_Worth_Knowing' => 'जानने योग्य कमांड',
'Woo_Worth_Knowing' => 'जानने योग्य',
'Woo_Guide_Changing_Url_Clears' => 'स्टोर URL या API कुंजियाँ बदलने से हर मैपिंग साफ़ हो जाती है — उत्पाद, श्रेणियाँ, ब्रांड और ग्राहक सभी नए स्टोर में फिर से सिंक होते हैं।',
'Woo_Guide_Keep_Skus' => 'Stocky और WooCommerce के बीच SKU एक जैसे रखें: इसी से डुप्लिकेट रुकते हैं और फिर से लिंक करना सुरक्षित होता है।',
'Woo_Guide_Stock_Total' => 'Woo पर प्रकाशित स्टॉक {total} है, किसी एक गोदाम का आँकड़ा नहीं।',
'Woo_Total_Across_Warehouses' => 'सभी गोदामों का कुल',
'Woo_Guide_Full_Reference' => 'पूरा संदर्भ — हर स्कोप, क्यू कैसे काम करती है, और समस्या-निवारण सूची — {file} में है।',
'Woo_Way_Covers' => 'शामिल है',
'Woo_Way_Covers_Realtime' => 'केवल ERP से बाहर जाने वाला स्टॉक — POS बिक्री, वापसी, समायोजन, प्राप्त खरीद',
'Woo_Way_Covers_Scheduled' => 'सब कुछ, दोनों दिशाओं में: ऑर्डर और उत्पाद बदलाव अंदर, कैटलॉग और स्टॉक बाहर',
'Woo_Way_Speed' => 'गति',
'Woo_Way_Seconds' => 'सेकंड',
'Woo_Way_Speed_Scheduled' => 'जो भी आप cron प्रविष्टि में डालें (घंटेवार स्टॉक, हर 15 मिनट में ऑर्डर)',
'Woo_Way_Needs' => 'आवश्यकता',
'Woo_Way_Needs_Realtime' => 'कुछ नहीं — बस सेटिंग',
'Woo_Way_Needs_Scheduled' => 'हर जॉब के लिए एक cron प्रविष्टि — या कुछ नहीं, यदि आप हाथ से सिंक करते हैं',
'Woo_Way_Switched_On_At' => 'यहाँ चालू किया जाता है',
'Woo_Way_Cron_Entries_Below' => 'नीचे दी गई cron प्रविष्टियाँ',
'Woo_Cron_Orders' => 'हर 15 मिनट में ऑर्डर — केवल वे जो पिछली बार के बाद बदले हैं।',
'Woo_Cron_Products_Pull' => 'शॉप से उत्पाद बदलाव, हर रात 03:00 बजे।',
'Woo_Cron_Customers' => 'ग्राहक, हर रात 03:30 बजे।',
'Woo_Cron_Stock' => 'हर घंटे स्टॉक — तत्काल पुश के नीचे सुरक्षा जाल, और उसके बिना एकमात्र स्टॉक सिंक।',
'Woo_Cron_Products_Push' => 'अभी तक लिंक न हुए उत्पाद, हर रात 02:00 बजे। मौजूदा उत्पाद दोबारा नहीं लिखे जाते।',
'Woo_Cmd_Stock' => 'हर लिंक किए गए उत्पाद का स्टॉक अभी पुश करें।',
'Woo_Cmd_Products_Unsynced' => 'वे उत्पाद प्रकाशित करें जिनकी अभी कोई WooCommerce ID नहीं है।',
'Woo_Cmd_Orders' => 'पिछली बार के बाद बदले ऑर्डर इम्पोर्ट करें।',
'Woo_Cmd_Orders_Full' => 'केवल हाल के बदलावों के बजाय हर ऑर्डर को फिर से स्कैन करें।',
'Woo_Cmd_Pull' => 'आने वाला सब कुछ एक साथ: उत्पाद, ऑर्डर, ग्राहक।',
'Woo_Guide_Page_Title' => 'WooCommerce गाइड',
'Woo_Guide_Page_Subtitle' => 'शॉप को कनेक्ट करना, क्या अपने आप चलता है, और इस सर्वर के लिए cron प्रविष्टियाँ',
'Woo_Settings_Button' => 'WooCommerce सेटिंग्स',
'Woo_No_Shop_Connected' => 'अभी कोई शॉप कनेक्ट नहीं है',
'Woo_No_Shop_Connected_Desc' => 'नीचे दी गई सारी जानकारी फिर भी लागू होती है — WooCommerce सेटिंग्स पेज पर स्टोर URL और API कुंजियाँ दर्ज करें, फिर वापस आएँ।',
'Woo_Wp_Username' => 'WordPress उपयोगकर्ता नाम',
'Woo_Wp_App_Password' => 'WordPress एप्लिकेशन पासवर्ड',
'Woo_Settings_Instant_Hint' => 'बिक्री, वापसी या समायोजन सहेजे जाते ही केवल उन्हीं उत्पादों के लिए स्टॉक पुश भेजता है, इसलिए शॉप अगले घंटेवार स्टॉक सिंक के बजाय कुछ ही सेकंड में सही हो जाती है। और कुछ इंस्टॉल करने की ज़रूरत नहीं — पुश बिक्री का जवाब दिए जाने के बाद चलता है, इसलिए काउंटर को कभी WooCommerce की प्रतीक्षा नहीं करनी पड़ती। अधिक जानकारी {guide} टैब पर।',
'Woo_Settings_Instant_Off_Alert' => 'इसे बंद छोड़ने पर POS बिक्री WooCommerce तक केवल अगले स्टॉक सिंक पर पहुँचती है — एक घंटे तक बाद।',
'Woo_Settings_Auto_Products_Hint' => 'Stocky में बनाया, संपादित या डुप्लिकेट किया गया उत्पाद सहेजे जाने के तुरंत बाद WooCommerce को भेजा जाता है — विवरण, मूल्य, वेरिएंट, छवियाँ, फिर उसका स्टॉक — उत्पाद सिंक की प्रतीक्षा किए बिना। बल्क इम्पोर्ट पुश नहीं होते; इम्पोर्ट के बाद उत्पाद सिंक चलाएँ।',
'Woo_Sync_Tuning' => 'सिंक ट्यूनिंग',
'Woo_Sync_Tuning_Intro' => 'डिफ़ॉल्ट मान अधिकांश स्टोर के लिए उपयुक्त हैं। इन्हें केवल तभी बदलें जब आपकी होस्टिंग पर सिंक धीमा हो या टाइम आउट हो। हर मान एक सुरक्षित सीमा तक सीमित है, और फ़ील्ड खाली करने से उसका डिफ़ॉल्ट मान वापस आ जाता है।',
'Woo_Setting_This_Up' => 'इसे सेट करना',
'Woo_Setting_This_Up_Text' => 'API कुंजियाँ प्राप्त करना, WordPress एप्लिकेशन पासवर्ड किसलिए है, शेड्यूल्ड सिंक के लिए cron प्रविष्टियाँ, और स्टॉक बदलते ही शॉप तक कैसे पहुँचाएँ — यह सब, इस सर्वर की अपनी cron लाइनों के साथ कॉपी करने के लिए तैयार, गाइड टैब पर है। एक ही प्रति, ताकि यह मॉड्यूल के वास्तविक व्यवहार से अलग न हो।',
