'Telegram_G_A_Body' => 'Stocky में सहेजी गई बिक्री, खरीद, भुगतान या व्यय — POS पर या एडमिन में — सहेजे जाने के {after} उसी अनुरोध में Telegram को भेजा जाता है। न cron प्रविष्टि, न क्यू वर्कर, और कैशियर को कभी Telegram की प्रतीक्षा नहीं करनी पड़ती: संदेश जाने तक बिक्री का जवाब दिया जा चुका होता है।',
'Telegram_G_Right_After' => 'तुरंत बाद',
