'Telegram_G_B_Body' => 'दो प्रकार के संदेश इसके बजाय Telegram की अपनी क्यू में प्रतीक्षा करते हैं: विफल भेजा गया संदेश (Telegram कुछ समय के लिए उपलब्ध नहीं), जिसे अगले कुछ मिनटों में तीन बार तक फिर से प्रयास किया जाता है; और एडमिन के बाहर उत्पन्न इवेंट — WooCommerce या Shopify से इम्पोर्ट किए गए ऑर्डर, artisan कमांड। यह cron प्रविष्टि इन्हें भेजती है, और कुछ नहीं:',
'Telegram_G_Cron_Note' => 'हर मिनट सही है: जब कुछ भी प्रतीक्षा में न हो तो रन तुरंत समाप्त हो जाता है। cPanel पर यह {cronJobs} में जाता है — यदि {php} पुराना है तो PHP 8.2+ का पूरा पथ उपयोग करें। Windows पर, Task Scheduler का उपयोग करें, प्रोग्राम {program}, आर्गुमेंट {args}, {path} में प्रारंभ करें।',
