'Telegram_G_Growing_Note' => '— यदि यह संख्या बढ़ती रहती है, तो cron प्रविष्टि नहीं चल रही है।',
'Telegram_G_Without_Cron' => 'Cron प्रविष्टि के बिना भी, Stocky में सहेजा गया सब कुछ तुरंत पहुँचता है; आप केवल पुनः प्रयास और इम्पोर्ट किए गए ऑर्डर खोते हैं।',
