'Salla_Guide_4' => 'ऐप के Webhooks पेज पर: {signature} सुरक्षा रणनीति चुनें, उसका सीक्रेट यहाँ Webhook सीक्रेट फ़ील्ड में कॉपी करें, कनेक्शन टैब पर दिखाया गया Webhook URL सेट करें, और कम से कम {e1}, {e2}, {e3}, {e4}, {e5} और {e6} को सब्सक्राइब करें।',
