'Presta_Shop_Language_Id' => 'शॉप भाषा ID',
'Presta_Shop_Language_Help' => 'पुश करते समय उत्पाद नामों के लिए उपयोग की जाने वाली भाषा ID (1 = शॉप की पहली भाषा)।',
'Presta_Push_Products_Desc' => 'PrestaShop पर गायब साधारण उत्पाद (उनके वर्तमान स्टॉक के साथ) बनाता है। पहले से लिंक किए गए उत्पाद और वेरिएंट वाले उत्पाद छोड़ दिए जाते हैं — उत्पाद विवरण PrestaShop में ही संपादित करते रहें, या स्थानीय प्रति रीफ़्रेश करने के लिए पुल करें।',
'Presta_Pull_Products_Desc' => 'PrestaShop उत्पाद इम्पोर्ट करता है, मौजूदा उत्पादों का संदर्भ (SKU) से मिलान करता है और बाकी को बनाता है। कॉम्बिनेशन उनके पैरेंट उत्पाद के रूप में इम्पोर्ट किए जाते हैं।',
'Presta_Reset_Product_Confirm' => 'उत्पाद लिंक रीसेट करें? ऑर्डर इतिहास अपने लिंक बनाए रखता है।',
'Presta_Push_Stock_Desc' => 'हर लिंक किए गए उत्पाद के लिए शॉप का स्टॉक (stock_availables) अपडेट करता है।',
'Presta_Pull_Orders_Desc' => 'शॉप ऑर्डर को बिक्री के रूप में इम्पोर्ट करता है ({ref} जैसे संदर्भ), नवीनतम पहले। पहले से इम्पोर्ट किए गए और रद्द किए गए ऑर्डर छोड़ दिए जाते हैं, इसलिए नियमित रूप से पुल करना सुरक्षित है। PrestaShop में Webhook नहीं हैं — व्यस्त अवधि के बाद इसे चलाएँ।',
'Presta_Guide_1' => 'अपने PrestaShop बैक ऑफ़िस में {menu} खोलें और वेबसर्विस सक्षम करें।',
'Presta_Guide_2' => 'एक नई कुंजी जोड़ें, {products} और {stock} पर {rw}, तथा {orders} और {customers} पर {view} अनुमति दें।',
'Presta_Guide_3' => 'कनेक्शन टैब पर स्टोर URL और कुंजी पेस्ट करें, सहेजें, और {test} चलाएँ।',
'Presta_Guide_4' => 'यदि शॉप में पहले से कैटलॉग है तो पहले उत्पाद पुल करें (संदर्भ/SKU से मिलान); गायब साधारण उत्पाद बनाने के लिए पुश करें।',
'Presta_Guide_5' => 'मात्रा बदलने पर स्टॉक पुश करें, और नियमित रूप से ऑर्डर पुल करें — PrestaShop में Webhook नहीं हैं, इसलिए ऑर्डर केवल पुल करने पर ही आते हैं।',
'Presta_Identity_Title' => 'उत्पाद की पहचान संदर्भ (SKU) है',
'Presta_Identity_Desc' => 'Stocky के उत्पाद कोड का मिलान PrestaShop के संदर्भ से किया जाता है। दोनों तरफ़ संदर्भ एक जैसे रखें; कॉम्बिनेशन (वेरिएंट) का ऑर्डर में संदर्भ से मिलान होता है, लेकिन इस संस्करण में उन्हें पुश नहीं किया जाता।',
'Xero_Hero_Title' => 'Xero लेखांकन सिंक',
'Xero_Hero_Desc' => 'अपने ग्राहकों को Xero संपर्कों के रूप में और अपनी बिक्री को इनवॉइस के रूप में पुश करें — बैंक खाता कॉन्फ़िगर होने पर भुगतान सहित।',
'Xero_App_Credentials_Accounts' => 'ऐप क्रेडेंशियल और खाते',
'Xero_From_Dev_App' => 'developer.xero.com पर आपके ऐप से',
'Xero_Sales_Account_Code' => 'बिक्री खाता कोड',
'Xero_Sales_Account_Help' => 'इनवॉइस लाइनों के लिए राजस्व खाता (\'200\' Xero का डिफ़ॉल्ट Sales खाता है)।',
'Xero_Payment_Account_Code' => 'भुगतान खाता कोड (वैकल्पिक)',
'Xero_Payment_Account_Ph' => 'उदा. 090',
'Xero_Payment_Account_Help' => 'एक बैंक खाता कोड। सेट होने पर, भुगतान की गई बिक्री इनवॉइस पर भुगतान भी दर्ज करती है; केवल इनवॉइस सिंक करने के लिए खाली छोड़ें।',
'Xero_Auto_Sync_Sales' => 'नई बिक्री को इनवॉइस के रूप में ऑटो-सिंक करें',
'Xero_Auto_Sync_Sales_Hint' => '(बिक्री बनते ही बैकग्राउंड में क्यू में डाली जाती है)',
'Xero_Org_Connection' => 'संगठन कनेक्शन',
'Xero_Organisation' => 'संगठन',
'Xero_Disconnect_Confirm' => 'Xero संगठन डिस्कनेक्ट करें? फिर से कनेक्ट करने तक सिंक रुका रहेगा।',
'Xero_Redirect_Uri_Title' => 'Xero ऐप के लिए रीडायरेक्ट URI',
'Xero_Redirect_Uri_Help' => '{link} पर एक "Web app" बनाएँ और यह रीडायरेक्ट URI पंजीकृत करें। ध्यान दें: Xero एक्सेस टोकन अपने आप रीफ़्रेश होते हैं, लेकिन 60 दिनों से अधिक निष्क्रिय कनेक्शन को फिर से कनेक्ट करना होगा।',
'Xero_Total_Customers' => 'कुल ग्राहक',
'Xero_Contacts_In_Xero' => 'Xero में संपर्क',
'Xero_Total_Sales' => 'कुल बिक्री',
'Xero_Invoices_In_Xero' => 'Xero में इनवॉइस',
'Xero_Payments_Recorded' => 'दर्ज किए गए भुगतान',
'Xero_Push_Customers_To' => '{name} पर ग्राहक पुश करें',
'Xero_Push_Customers_Desc' => 'हर ग्राहक के लिए एक Xero संपर्क बनाता या अपडेट करता है। जिस ग्राहक का नाम Xero में पहले से मौजूद है, उसे उसी संपर्क से लिंक किया जाता है।',
'Xero_Push_Customers' => 'ग्राहक पुश करें',
'Xero_Push_Sales_Invoices' => 'बिक्री को इनवॉइस के रूप में पुश करें',
'Xero_Push_Invoices_Desc' => 'हर बिक्री के लिए एक AUTHORISED इनवॉइस बनाता है (इनवॉइस नंबर = बिक्री Ref), बिक्री की लाइन आइटम के साथ शिपिंग, छूट और कर लाइनें भी, ताकि Xero का कुल बिक्री के कुल से मेल खाए। Xero में पहले से मौजूद बिक्री छोड़ दी जाती है — इनवॉइस कभी संपादित नहीं किए जाते। गायब संपर्क तुरंत बना दिए जाते हैं।',
'Xero_Push_Invoices' => 'इनवॉइस पुश करें',
'Xero_Reset_Contact_Confirm' => 'संपर्क लिंक रीसेट करें? अगला पुश उन्हें फिर से लिंक करता है या दोबारा बनाता है।',
'Xero_Reset_Contact_Links' => 'संपर्क लिंक रीसेट करें',
'Xero_Guide_1' => '{link} पर एक {webApp} बनाएँ ({menu})।',
'Xero_Guide_2' => 'कनेक्शन टैब पर दिखाया गया रीडायरेक्ट URI पंजीकृत करें।',
'Xero_Guide_3' => 'ऐप का {clientId} कॉपी करें और एक {clientSecret} बनाएँ; दोनों को यहाँ पेस्ट करें और सहेजें।',
'Xero_Guide_4' => '{connect} पर क्लिक करें, साइन इन करें और कनेक्ट करने के लिए संगठन चुनें।',
'Xero_Guide_5' => 'खाता कोड जाँचें: बिक्री खाते में इनवॉइस लाइनें जाती हैं; यदि भुगतान की गई बिक्री के भुगतान भी दर्ज होने चाहिए तो बैंक खाता कोड सेट करें।',
'Xero_Guide_6' => 'पहले ग्राहक पुश करें, फिर इनवॉइस। इनवॉइस नंबर बिक्री Ref होते हैं, इसलिए लिंक रीसेट होने पर भी Xero डुप्लिकेट अस्वीकार कर देता है।',
'Xero_Amounts_Title' => 'राशियाँ कर-सहित, जैसी हैं वैसी ही पुश की जाती हैं',
'Xero_Amounts_Desc' => 'इनवॉइस NoTax लाइनों का उपयोग करते हैं जो बिक्री को बिल्कुल वैसा ही दर्शाती हैं (आइटम + शिपिंग − छूट + कर), इसलिए Xero का कुल हमेशा Stocky के कुल के बराबर होता है। आपका लेखाकार Xero के अंदर कर और शिपिंग लाइनों को सही खातों में फिर से मैप कर सकता है।',
'Xero_Org_Connected' => 'Xero संगठन कनेक्ट हो गया।',
'Jumia_Hero_Title' => 'Jumia मार्केटप्लेस सिंक',
'Jumia_Hero_Desc' => 'अपनी Jumia Seller Center लिस्टिंग पर मूल्य और स्टॉक पुश करें और मार्केटप्लेस ऑर्डर को बिक्री के रूप में इम्पोर्ट करें।',
'Jumia_Api_Url_Label' => 'API URL (आपके देश का Seller Center एंडपॉइंट)',
'Jumia_Account_Email' => 'खाता Email (User ID)',
'Jumia_Api_Key' => 'API कुंजी',
'Jumia_Prices_Stock' => 'मूल्य और स्टॉक',
'Jumia_Push_Prices_Stock_Title' => 'Jumia पर मूल्य और स्टॉक पुश करें',
'Jumia_Push_Prices_Stock_Desc' => 'हर उस उत्पाद (और वेरिएंट) का वर्तमान मूल्य और मात्रा भेजता है जिसका SKU Jumia लिस्टिंग के {sku} से मेल खाता है। अपडेट Seller Center फ़ीड के रूप में सबमिट होते हैं और एसिंक्रोनस रूप से लागू होते हैं — फ़ीड ID लॉग टैब में दर्ज होती है, और प्रति-आइटम अस्वीकृतियाँ Seller Center की फ़ीड स्थिति स्क्रीन पर दिखाई देती हैं।',
'Jumia_Push_Prices_Stock' => 'मूल्य और स्टॉक पुश करें',
'Jumia_Pull_Orders_Desc' => 'मार्केटप्लेस ऑर्डर को बिक्री के रूप में इम्पोर्ट करता है ({ref} जैसे संदर्भ), Seller SKU द्वारा आपके उत्पादों से मिलान करके। पहले से इम्पोर्ट किए गए और रद्द किए गए ऑर्डर छोड़ दिए जाते हैं, इसलिए नियमित रूप से पुल करना सुरक्षित है। भुगतान केवल डिलीवर हुए ऑर्डर के लिए ही भुगतान किया गया चिह्नित होते हैं (Jumia में अधिकतर COD होता है)।',
'Jumia_Guide_1' => 'Jumia {sellerCenter} में, {menu} खोलें और एक API कुंजी बनाएँ।',
'Jumia_Guide_2' => 'अपने देश का API URL दर्ज करें (जैसे नाइजीरिया के लिए {ng}, केन्या के लिए {ke}, मिस्र के लिए {eg}), अपना Seller Center खाता Email, और कुंजी — फिर {test} चलाएँ।',
'Jumia_Guide_3' => 'सुनिश्चित करें कि हर Jumia लिस्टिंग का {sku} Stocky उत्पाद कोड के बराबर हो — स्टॉक पुश और ऑर्डर मिलान दोनों के लिए यही पहचान उपयोग होती है।',
'Jumia_Guide_4' => 'इन्वेंटरी बदलने के बाद मूल्य और स्टॉक पुश करें; नियमित रूप से ऑर्डर पुल करें (इस API में Jumia के Webhook नहीं हैं)।',
'Jumia_Guide_5' => 'नई लिस्टिंग बनाना Seller Center में ही होता है — Jumia को श्रेणी-विशिष्ट विशेषताएँ और छवि समीक्षा चाहिए, जिन्हें केवल उनका पोर्टल ही ठीक से संभालता है।',
'Mailchimp_Hero_Title' => 'Mailchimp ऑडियंस सिंक',
'Mailchimp_Hero_Desc' => 'Mailchimp ऑडियंस को अपने ग्राहकों से भरा रखें, ताकि आप अपने वास्तविक ग्राहक आधार पर Email अभियान चला सकें।',
'Mailchimp_Account_Audience' => 'खाता और ऑडियंस',
'Mailchimp_Api_Key_Ph' => 'उदा. {example} ({menu})',
'Mailchimp_Audience_Option' => '{name} ({n} सदस्य)',
'Mailchimp_Load_Audiences_Ph' => 'एक चुनने के लिए ऑडियंस लोड करें',
'Mailchimp_Load_Audiences' => 'ऑडियंस लोड करें',
'Mailchimp_Double_Optin_Label' => 'डबल ऑप्ट-इन — नए सदस्यों को जुड़ने से पहले पुष्टि Email मिलता है',
'Mailchimp_Double_Optin_Hint' => '(GDPR के लिए अनुशंसित)',
'Mailchimp_Auto_Sync_Customers' => 'नए ग्राहकों को बनते ही ऑटो-सिंक करें',
'Mailchimp_With_Email' => 'Email वाले',
'Mailchimp_Push_Desc' => 'Email पते वाले हर ग्राहक को चयनित ऑडियंस में जोड़ता या अपडेट करता है (नाम और फ़ोन सहित)। मौजूदा सदस्यों की सदस्यता स्थिति बनी रहती है — अनसब्सक्राइब करने वाले किसी को फिर से सब्सक्राइब नहीं किया जाता। बिना Email वाले ग्राहक छोड़ दिए जाते हैं।',
'Mailchimp_Double_Optin_Off_Title' => 'डबल ऑप्ट-इन बंद है',
'Mailchimp_Double_Optin_Off_Desc' => 'नए सदस्य बिना पुष्टि Email के सब्सक्राइब्ड के रूप में जोड़े जाएँगे। ऐसा केवल उन्हीं ग्राहकों के लिए करें जो पहले से मार्केटिंग प्राप्त करने के लिए सहमत हैं।',
'Mailchimp_Guide_1' => 'Mailchimp में {menu} खोलें और एक कुंजी बनाएँ (यह {suffix} पर समाप्त होती है — वह प्रत्यय आपका डेटासेंटर है)।',
'Mailchimp_Guide_2' => 'कुंजी यहाँ पेस्ट करें, सहेजें, फिर {load} पर क्लिक करें और भरने के लिए ऑडियंस चुनें।',
'Mailchimp_Guide_3' => '{doubleOptIn} चालू रखें, जब तक आपके ग्राहक पहले से मार्केटिंग Email के लिए सहमति न दे चुके हों।',
'Mailchimp_Double_Optin_Term' => 'डबल ऑप्ट-इन',
'Mailchimp_Guide_4' => 'प्रारंभिक भराई के लिए {push} चलाएँ; {autoSync} चालू करें ताकि नए ग्राहक अपने आप जुड़ें।',
'Mailchimp_Auto_Sync_Term' => 'ऑटो-सिंक',
'Mailchimp_Consent_Title' => 'सहमति महत्वपूर्ण है',
'Mailchimp_Consent_Desc' => 'ऐसे लोगों को Email भेजना जिन्होंने कभी मार्केटिंग के लिए सहमति नहीं दी, GDPR/CAN-SPAM का उल्लंघन हो सकता है और आपका Mailchimp खाता निलंबित हो सकता है। डबल ऑप्ट-इन पुष्टि की ज़िम्मेदारी Mailchimp पर डालता है — यही सुरक्षित डिफ़ॉल्ट है।',
'Mailchimp_No_Audiences' => 'इस खाते में कोई ऑडियंस नहीं मिली।',
'GSheets_Hero_Title' => 'Google Sheets एक्सपोर्ट',
'GSheets_Hero_Desc' => 'अपनी बिक्री, उत्पाद और ग्राहकों को एक लाइव Google स्प्रेडशीट में एक्सपोर्ट करें — हर एक का अलग टैब, माँग पर रीफ़्रेश।',
'GSheets_OAuth_Credentials' => 'Google OAuth क्रेडेंशियल',
'GSheets_Client_Secret_Ph' => 'आपके Google Cloud OAuth क्लाइंट से',
'GSheets_Auto_Export' => 'हर रात ऑटो-एक्सपोर्ट',
'GSheets_Auto_Export_Hint' => '(सभी टैब सर्वर समय के अनुसार लगभग 02:30 बजे रीफ़्रेश होते हैं)',
