'Shopify_Could_Not_Load_Store' => 'यह स्टोर लोड नहीं कर सके',
'Shopify_G_Lead_Store' => 'इस शॉप को तालमेल में बने रहने के लिए क्या चाहिए। यहाँ की हर चीज़ इसी स्टोर के लिए है — पाथ और ID असली हैं, इसलिए कमांड सीधे सर्वर पर कॉपी किए जा सकते हैं।',
'Shopify_G_Lead_Generic' => 'एक Shopify शॉप ERP के साथ तालमेल में कैसे रहती है। उसकी अपनी स्थिति देखने के लिए ऊपर एक स्टोर चुनें, या इसे वैसे ही पढ़ें — cron लाइन और Webhook URL वही रहते हैं चाहे आप कोई भी स्टोर कनेक्ट करें।',
'Shopify_G_Ways_Note' => 'अधिकांश शॉप दोनों चलाती हैं: पहला तरीका शॉप को मिनट-दर-मिनट अपडेट रखता है, दूसरा वह सब पकड़ता है जो पहले से छूट गया — कोई Webhook जो कभी नहीं पहुँचा, Shopify एडमिन में सीधे किया गया कोई बदलाव, कोई रात जब साइट बंद थी।',
'Shopify_G_Both_Need' => 'दोनों तरीकों के लिए पहले यह चाहिए',
'Shopify_G_Credentials' => 'Shopify क्रेडेंशियल',
'Shopify_G_Cred_Intro' => 'जनवरी 2026 से Shopify एडमिन के अंदर कस्टम ऐप नहीं बनाता, इसलिए दो तरह के कनेक्शन होते हैं:',
'Shopify_G_Cred_DevDash' => '{app} (अब कनेक्ट की गई कोई भी शॉप) — {path}। यह स्टोर जो सिंक करता है उसके लिए Admin API स्कोप दें, ऐप को शॉप पर इंस्टॉल करें, फिर ऐप के सेटिंग्स पेज से {clientId} और {clientSecret} को {where} में कॉपी करें। ERP खुद इनके बदले एक्सेस टोकन लेता है और हर 24 घंटे में उसकी समय-सीमा खत्म होने से पहले उसे नवीनीकृत करता है। client secret Webhook पर भी हस्ताक्षर करता है, इसलिए और कुछ नहीं चाहिए। ऐप और शॉप एक ही Shopify संगठन में होने चाहिए।',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard ऐप',
'Shopify_G_Cred_Legacy' => '{app} (2026 से पहले एडमिन में बनाया गया) — अपने {token} ({prefix}) और Webhook साइनिंग सीक्रेट के रूप में अपनी {secret} के साथ बिना बदलाव के काम करता रहता है। यह टोकन जैसा मान नहीं है, और इन्हें उलट देना Webhook अस्वीकार होने का आम कारण है।',
'Shopify_G_Legacy_App' => 'पुराना कस्टम ऐप',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'सहेजा गया',
'Shopify_G_Missing_Refused' => 'मौजूद नहीं — डिलीवरी अस्वीकार होंगी',
'Shopify_G_Where_Data_Desc' => '{path} वह ERP गोदाम जिसका स्टॉक यह शॉप बेचती है, और वह Shopify लोकेशन जिसमें वह स्टॉक लिखा जाता है। इनके बिना इन्वेंटरी सिंक और ऑर्डर इम्पोर्ट दोनों चलने से मना करते हैं।',
'Shopify_G_Currently' => 'वर्तमान में: गोदाम {warehouse}, लोकेशन {location}',
'Shopify_G_Not_Set_Lower' => 'सेट नहीं',
'Shopify_G_Ready' => 'तैयार',
'Shopify_G_Incomplete' => 'अधूरा',
'Shopify_G_Manual_Syncs' => 'आपके द्वारा मैन्युअल रूप से शुरू किए गए सिंक',
'Shopify_G_Manual_Desc' => '{centre} से शुरू किया गया सिंक तुरंत जवाब देता है और बैकग्राउंड में छोटे-छोटे हिस्सों में चलता है, जिनमें से हर एक वहीं से जारी रहता है जहाँ पिछला रुका था। लंबे वेब अनुरोधों को समाप्त करने वाली होस्टिंग (LiteSpeed, nginx, लोड बैलेंसर) के कारण बड़ा कैटलॉग कभी बीच में नहीं कटता, और पेज बंद करने से यह नहीं रुकता। इसके लिए वर्कर एक और cron लाइन है:',
'Shopify_G_Cron_Copied' => 'Cron लाइन कॉपी की गई',
'Shopify_G_Manual_Note' => 'इसके बिना भी सिंक पूरा होता है, लेकिन केवल तब तक जब तक सिंक सेंटर पेज खुला रहे: जब कुछ सेकंड में कोई वर्कर रन नहीं उठाता, तो पेज खुद उसे एक-एक छोटे अनुरोध से आगे बढ़ाता है। Windows पर हर मिनट Task Scheduler का उपयोग करें: प्रोग्राम {program}, आर्ग्युमेंट {args}, शुरू करने का फ़ोल्डर {dir}।',
'Shopify_G_Then_Pick' => 'फिर चुनें कि यह तालमेल में कैसे रहे',
'Shopify_G_Right_Away' => 'तुरंत',
'Shopify_G_Stock_Live' => 'स्टॉक लाइव',
'Shopify_G_Stock_Not_Live' => 'स्टॉक लाइव नहीं',
'Shopify_G_Realtime_Lead' => 'हर बदलाव होते ही कुछ सेकंड में भेजा जाता है। इसके दो हिस्से हैं, और उनके अलग-अलग स्विच हैं: {webhooks} शॉप के अपने इवेंट अंदर लाते हैं, और {push} स्टॉक बाहर भेजता है।',
'Shopify_G_Webhooks_Lower' => 'Webhook',
'Shopify_G_Instant_Push_Lower' => 'तत्काल स्टॉक पुश',
'Shopify_G_Webhooks_In' => 'Webhook — शॉप → ERP',
'Shopify_G_Webhooks_Desc' => 'Shopify में किए गए ऑर्डर, ऑर्डर स्थिति में बदलाव, और उत्पाद, ग्राहक व स्टॉक में बदलाव। स्टोर खोलें और उसके {tab} पर {button} दबाएँ — दो बार दबाना सुरक्षित है। Shopify यहाँ पोस्ट करता है:',
'Shopify_G_Webhooks_Tab' => 'Webhook टैब',
'Shopify_G_Webhooks_Note' => 'यह पता इंटरनेट से HTTPS पर पहुँच योग्य होना चाहिए — Shopify {localhost} या {test} डोमेन पर डिलीवर नहीं करेगा। हर डिलीवरी एक बार दर्ज होती है, इसलिए Shopify के पुनः प्रयास डुप्लिकेट ऑर्डर नहीं बना सकते, और विफल डिलीवरी को दोबारा चलाया जा सकता है। चरण 1 का साइनिंग सीक्रेट सहेजे जाने तक डिलीवरी अस्वीकार होती हैं।',
'Shopify_G_Instant_Out' => 'तत्काल स्टॉक पुश — ERP → शॉप',
'Shopify_G_Setting_Missed' => 'यही वह सेटिंग है जो लोग भूल जाते हैं',
'Shopify_G_Pos_Not_Auto' => 'POS बिक्री अपने आप Shopify तक {not} पहुँचती। इसे बंद छोड़ने पर शॉप को केवल अगले इन्वेंटरी पुश चरण पर पता चलता है — और उस बीच वह ऐसी यूनिट बेच सकती है जिसे आप काउंटर पर पहले ही बेच चुके हैं।',
'Shopify_G_Not' => 'नहीं',
'Shopify_G_Tick_Push' => '{where} पर {setting} चुनें। बस इतना ही सेटअप है — कोई वर्कर नहीं, कोई cron नहीं। इसके बाद हर बिक्री, वापसी और समायोजन बिक्री सहेजे जाने के ठीक बाद केवल उन्हीं उत्पादों का पुश भेजता है, और बीस पंक्तियों वाली बिक्री पर एक ही पुश होता है, बीस नहीं। कैश काउंटर कभी इसका इंतज़ार नहीं करता।',
'Shopify_G_This_Store' => 'यह स्टोर:',
'Shopify_G_Push_On' => 'चालू — बदलाव पर स्टॉक पुश होता है',
'Shopify_G_Push_Off' => 'बंद — स्टॉक केवल शेड्यूल पर',
'Shopify_G_Push_Note' => 'केवल वे उत्पाद पुश होते हैं जिनकी पहले से Shopify मैपिंग है, और केवल इस स्टोर के गोदाम की गतिविधियाँ। बल्क ऑपरेशन — कोई उत्पाद हटाना, गोदाम रीसेट करना — बिना इवेंट चलाए स्टॉक लिखते हैं, जो शेड्यूल्ड इन्वेंटरी चरण भी बनाए रखने का एक कारण है।',
'Shopify_G_Nothing_Install' => 'और कुछ इंस्टॉल करने की ज़रूरत नहीं',
'Shopify_G_No_Worker_Note' => 'किसी भी हिस्से को क्यू वर्कर या cron प्रविष्टि की ज़रूरत नहीं है। आने वाला Webhook Shopify के अनुरोध में ही संभाला जाता है; बाहर जाने वाला स्टॉक पुश उसी प्रोसेस में चलता है जिसने बिक्री संभाली, प्रतिक्रिया वापस जाने के {after} — इसलिए कैश काउंटर कभी Shopify का इंतज़ार नहीं करता, और जवाब देना बंद करने वाली शॉप को दस सेकंड बाद छोड़ दिया जाता है और मामला अगले शेड्यूल्ड इन्वेंटरी पुश पर रहता है।',
'Shopify_G_After' => 'बाद',
'Shopify_G_Artisan_Note' => 'एक अपवाद: artisan कमांड द्वारा किए गए स्टॉक बदलाव के बाद कोई प्रतिक्रिया नहीं होती, इसलिए उसे इसके बजाय {queue} पर कतार में रखा जाता है। यदि आप चाहते हैं कि वे भी तुरंत जाएँ, तो उस क्यू को प्रोसेस करें:',
'Shopify_G_On_Schedule' => 'शेड्यूल पर',
'Shopify_G_On_Lower' => 'चालू',
'Shopify_G_Off_Lower' => 'बंद',
'Shopify_G_Scheduled_Lead' => 'सब कुछ समय-समय पर दोनों दिशाओं में दोबारा जाँचा जाता है। यह रियल-टाइम से धीमा है, लेकिन यही उन शॉप पर स्टॉक पुश करता है जो तत्काल पुश का उपयोग नहीं करतीं, यही छूटे हुए Webhook को पकड़ता है, और पूरा कैटलॉग भेजने का यही एकमात्र तरीका है।',
'Shopify_G_Cron_Entry' => 'Cron प्रविष्टि',
'Shopify_G_Cron_Entry_Desc' => 'इसके बिना कुछ भी शेड्यूल्ड नहीं चलता। एक लाइन, केवल इस मॉड्यूल के लिए — इसे उन अन्य चीज़ों के साथ जोड़ें जिन्हें आपने शेड्यूल करना चुना है:',
'Shopify_G_Cron_Note' => 'हर पाँच मिनट वह सबसे बारीक अंतराल है जिसे कोई योजना उपयोग कर सकती है, क्योंकि पाँच मिनट सबसे छोटा चरण अंतराल है। अधिक अंतराल वाली प्रविष्टि बस न्यूनतम सीमा बन जाती है — {example} के साथ, 5 मिनट पर सेट चरण हर 15 मिनट में चलता है। Windows पर Task Scheduler का उपयोग करें: प्रोग्राम {program}, आर्ग्युमेंट {args}, शुरू करने का फ़ोल्डर {dir}।',
'Shopify_G_Switch_On_Plan' => 'इसे चालू करें, और योजना चुनें',
'Shopify_G_Plan_Desc' => '{where} स्विच तय करता है कि cron कुछ कर सकता है या नहीं; योजना तय करती है कि वह क्या करता है। एक {step} अपने अंतराल के साथ एक दिशा में एक एंटिटी है — {first}, {second}। डिफ़ॉल्ट अंतराल उस हर चरण द्वारा उपयोग किया जाता है जिसका अपना बॉक्स खाली है।',
'Shopify_G_Step_Lower' => 'चरण',
'Shopify_G_Plan_Note' => 'योजना खाली छोड़ें तो स्टोर डिफ़ॉल्ट अंतराल पर ऑर्डर पुल करता है और स्टॉक पुश करता है, जो अधिकांश शॉप चाहती हैं। ऑर्डर केवल पुल होते हैं: ग्राहक ऑर्डर Shopify पर ही देता है।',
'Shopify_G_Schedule_On' => 'शेड्यूल चालू',
'Shopify_G_Schedule_Off' => 'शेड्यूल बंद — केवल मैन्युअल',
'Shopify_G_When_Step_Runs' => 'कोई चरण वास्तव में कब चलता है',
'Shopify_G_When_Note' => 'कोई चरण तब देय होता है जब वही चरण पिछली बार उसके अंतराल से अधिक समय पहले {started} हुआ हो, जो रन इतिहास से पढ़ा जाता है। इसलिए मैन्युअल रूप से शुरू किया गया सिंक अगले स्वचालित सिंक को टाल देता है, और बार-बार विफल होने वाला चरण हर टिक पर नहीं बल्कि अपने अंतराल पर दोबारा आज़माया जाता है। स्टोर का ओवरव्यू हर चरण का अंतिम रन, अगला देय समय, और ब्लॉक होने पर उसका कारण दिखाता है। पहला कैटलॉग पुश शेड्यूल पर डालने से पहले मैन्युअल रूप से चलाएँ — पहले {dryRun} के साथ।',
'Shopify_G_Started_Lower' => 'शुरू',
'Shopify_G_Where_Setting' => 'हर सेटिंग कहाँ है',
'Shopify_G_Where_Setting_Note' => 'ये सभी किसी मौजूदा स्टोर पर हैं: {path}, फिर पेंसिल (या स्टोर के अपने पेज पर {edit})।',
'Shopify_G_Product_Images' => 'उत्पाद चित्र',
'Shopify_G_Img_1' => 'चित्र {push} पर उत्पाद के साथ जाते हैं — पहले मुख्य चित्र, फिर गैलरी, फिर अपने चित्र वाले हर वेरिएंट का एक, अधिकतम पचास तक।',
'Shopify_G_Products_Push' => 'उत्पाद पुश',
'Shopify_G_Img_2' => 'वेरिएंट का चित्र उत्पाद के साथ अपलोड होता है और फिर {assigned} जाता है, Shopify इसे इसी तरह मॉडल करता है: एक वेरिएंट उत्पाद के किसी एक चित्र की ओर इशारा करता है। मुख्य चित्र का दोबारा उपयोग करने वाला वेरिएंट उसे दो बार अपलोड नहीं करता।',
'Shopify_G_Assigned' => 'उस वेरिएंट को असाइन किया',
'Shopify_G_Img_3' => 'फ़ाइल के रूप में सहेजा गया चित्र Shopify पर {uploaded} किया जाता है, लिंक नहीं, इसलिए यह तब भी काम करता है जब यह इंस्टॉलेशन इंटरनेट से पहुँच योग्य न हो। पेस्ट किए गए लिंक के रूप में जोड़ा गया चित्र Shopify को उसी URL के रूप में दिया जाता है, जो सार्वजनिक रूप से पहुँच योग्य होना चाहिए।',
'Shopify_G_Uploaded' => 'अपलोड',
'Shopify_G_Img_4' => 'इन्हें केवल तभी दोबारा भेजा जाता है जब ये वास्तव में बदलते हैं — केवल मूल्य बदलने वाला पुश शॉप के चित्रों को नहीं छूता, क्योंकि इन्हें भेजने से पूरा सेट बदल जाता है।',
'Shopify_G_Img_5' => 'ERP में चित्र हटाने से वह Shopify में {not} हटता। उसे वहाँ भी हटाएँ, नहीं तो शॉप उसे दिखाती रहेगी।',
'Shopify_G_Commands' => 'जानने योग्य कमांड',
'Shopify_G_Command_Copied' => 'कमांड कॉपी की गई',
