'StoreAdm_PG_Intro_Msg' => 'PayPal, Paystack, Flutterwave, Razorpay, bKash और SSLCommerz का उपयोग केवल ऑनलाइन स्टोर चेकआउट में होता है।',
'StoreAdm_PG_Intro_Desc' => 'Stripe कुंजियाँ वैश्विक रूप से साझा होती हैं (एडमिन और ऑनलाइन स्टोर एक ही Stripe इंटीग्रेशन का उपयोग करते हैं)। हर टैब ऑनलाइन स्टोर चेकआउट के लिए अपनी भुगतान विधि को चालू या बंद करता है; ऑफ़लाइन भुगतान में सिस्टम के बाहर भुगतान की जाने वाली विधियाँ होती हैं।',
