'StoreAdm_PG_Paystack_Test_Live' => 'परीक्षण या लाइव, यह कुंजी जोड़ी से तय होता है: {test} कुंजियाँ परीक्षण मोड में चलती हैं, {live} कुंजियाँ वास्तविक कार्ड से शुल्क लेती हैं — कोई अलग सैंडबॉक्स स्विच नहीं है।',
