'StoreAdm_PG_Paystack_Disabled_Desc' => 'ऑनलाइन स्टोर चेकआउट पर कार्ड, बैंक ट्रांसफ़र और मोबाइल मनी स्वीकार करने के लिए Paystack चालू करें और अपनी Public और Secret keys ({site} → Settings → API Keys से) दर्ज करें।',
