'StoreAdm_PG_Flutterwave_Info' => 'क्लासिक कुंजियों के साथ Flutterwave v3 API का उपयोग करता है। परीक्षण या लाइव, यह कुंजी जोड़ी से तय होता है ({keys} बनाम लाइव कुंजियाँ) — कोई अलग सैंडबॉक्स स्विच नहीं है। स्टोर की मुद्रा आपके Flutterwave खाते पर सक्षम होनी चाहिए।',
'StoreAdm_PG_Flutterwave_Webhook_Url' => 'Webhook URL (वैकल्पिक बैकअप — इसे ऊपर दिए गए Secret Hash के साथ Flutterwave डैशबोर्ड पर सेट करें):',
'StoreAdm_PG_Flutterwave_Disabled_Desc' => 'ऑनलाइन स्टोर चेकआउट पर कार्ड, मोबाइल मनी और बैंक ट्रांसफ़र स्वीकार करने के लिए Flutterwave चालू करें और अपनी v3 Public और Secret keys ({site} → Settings → API से) दर्ज करें।',
