'StoreAdm_PG_Bkash_Info' => 'bKash Tokenized Checkout का उपयोग करता है (bKash मर्चेंट पोर्टल से मर्चेंट क्रेडेंशियल)। bKash केवल BDT में शुल्क लेता है — यह विकल्प चेकआउट पर केवल तभी दिखाया जाता है जब स्टोर की सक्रिय मुद्रा BDT हो।',
