'Cr_Guide_Meaning' => 'अर्थ',
'Cr_Guide_T_Statuses' => 'स्थितियाँ',
'Cr_Guide_Statuses_Note' => 'स्थितियाँ केवल आगे बढ़ती हैं, इसलिए देर से आया अपडेट किसी पार्सल को कभी पीछे नहीं ले जाता। डिलीवर हो चुके पार्सल को भी वापसी में या वापस आया हुआ बताया जा सकता है।',
'Cr_Guide_S_booked' => 'ऑर्डर कूरियर के पास है; अभी तक किसी ने इसे उठाया नहीं है। बुकिंग केवल इसी समय रद्द की जा सकती है।',
