'Cr_Guide_S_out_for_delivery' => 'आज राइडर के पास।',
'Cr_Guide_S_failed_attempt' => 'घर पर नहीं, अस्वीकार किया गया या गलत पता। कूरियर फिर से प्रयास करता है या इसे वापस करता है।',
'Cr_Guide_S_delivered' => 'ग्राहक को सौंप दिया गया। COD राशि कूरियर द्वारा वसूली गई मानी जाती है।',
'Cr_Guide_S_returning' => 'आपके पास वापस आ रहा है।',
'Cr_Guide_S_returned' => 'आपके पास वापस: यह समीक्षा के लिए वापसी में प्रतीक्षा करता है, या स्वचालित रूप से फिर से स्टॉक में जोड़ा जाता है।',
'Cr_Guide_S_cancelled' => 'बुकिंग रद्द कर दी गई।',
'Cr_Guide_T_Booking' => 'ऑर्डर बुक करना',
'Cr_Guide_B_Booking' => '"कूरियर को भेजें" बिक्री से फ़ॉर्म भरता है: प्राप्तकर्ता, पता, COD के रूप में अभी भी बकाया राशि, और उत्पादों का वज़न। जिन कूरियर की अपनी शहर सूचियाँ होती हैं वे एक चयनकर्ता दिखाते हैं, और आपका चयन उस शहर के लिए याद रखा जाता है। एग्रीगेटर, DHL, FedEx, UPS और Lalamove "दरों की तुलना करें" देते हैं: एक मूल्य चुनें और "बुक करें" उसे खरीद लेता है। बिक्री सूची से कई बिक्रियाँ एक साथ बुक की जा सकती हैं।',
'Cr_Guide_T_Cod' => 'कैश ऑन डिलीवरी',
'Cr_Guide_B_Cod' => 'एक COD पार्सल "वसूल नहीं हुआ" से "कूरियर द्वारा वसूला गया" (डिलीवरी पर) और फिर "आपको भुगतान किया गया" तक जाता है। जो कूरियर भुगतान की रिपोर्ट करते हैं वे अंतिम चरण स्वयं पूरा करते हैं; अन्य के लिए "COD अपडेट करें" का उपयोग करें। कूरियर सेटिंग्स में खाता चुने होने पर, भुगतान को बिक्री पर एक भुगतान के रूप में दर्ज किया जाता है। पार्सल पूरा होने के बाद कूरियर शुल्क को व्यय के रूप में सहेजा जा सकता है।',
'Cr_Guide_T_Returns' => 'वापस आए पार्सल',
'Cr_Guide_B_Returns' => 'डिफ़ॉल्ट रूप से वापस आया पार्सल कूरियर शिपमेंट में "समीक्षा हेतु वापसी" के अंतर्गत प्रतीक्षा करता है। "फिर से स्टॉक करें" पूरे ऑर्डर के लिए बिक्री वापसी बनाता है और आइटम वापस स्टॉक में डालता है; "खारिज करें" कुछ भी वापस नहीं डालता, क्षतिग्रस्त या खोए हुए पार्सल के लिए। इसके बजाय कूरियर सेटिंग्स स्वचालित रूप से फिर से स्टॉक कर सकती हैं।',
'Cr_Guide_T_Customers' => 'ग्राहक संदेश और ट्रैकिंग पेज',
'Cr_Guide_B_Customers' => 'कूरियर सेटिंग्स में ग्राहक सूचनाएँ आपके द्वारा टिक की गई स्थितियों पर SMS, Email या WhatsApp भेजती हैं, प्रत्येक पार्सल के लिए एक बार, आपके अपने टेक्स्ट के साथ। आपके ऑनलाइन स्टोर का ट्रैकिंग पेज ग्राहकों को ट्रैकिंग नंबर, या ऑर्डर नंबर और फ़ोन से पार्सल ट्रैक करने देता है। जो ग्राहक अक्सर पार्सल लौटाते हैं, उन्हें बुकिंग करते समय वापसी-जोखिम बैज मिलता है।',
'Cr_Guide_T_Labels' => 'लेबल',
'Cr_Guide_B_Labels' => '"लेबल प्रिंट करें" कूरियर का अपना लेबल देता है जब वह जारी करता है (PDF, लिंक या छवि), अन्यथा ट्रैकिंग बारकोड और वसूली जाने वाली राशि के साथ एक Stocky लेबल। प्रिंट करने के लिए इस साइट के लिए पॉप-अप की अनुमति दें। DHL, FedEx और UPS अपना लेबल केवल एक बार, बुकिंग के समय देते हैं, और Stocky इसे दोबारा प्रिंट करने के लिए रखता है।',
'Cr_Guide_T_Faq' => 'समस्या निवारण',
'Cr_Guide_Q_Test' => 'कनेक्शन परीक्षण विफल होता है',
'Cr_Guide_A_Test' => 'टेस्ट-मोड कुंजियाँ टेस्ट मोड के साथ और लाइव कुंजियाँ लाइव के साथ उपयोग होती हैं; ये अलग-अलग हैं। सटीक कारण के लिए कूरियर लॉग खोलें और कूरियर का उत्तर पढ़ें।',
'Cr_Guide_Q_City' => 'कूरियर शहर या पता अस्वीकार करता है',
'Cr_Guide_A_City' => 'बुकिंग फ़ॉर्म में कूरियर की शहर सूची से शहर चुनें; कूरियर केवल अपने नाम स्वीकार करते हैं। जो कूरियर डाक पतों के साथ काम करते हैं उन्हें राज्य, पिन कोड और दो-अक्षर का देश कोड भी चाहिए।',
'Cr_Guide_Q_Webhook' => 'स्थितियाँ अपने आप नहीं बदलतीं',
'Cr_Guide_A_Webhook' => 'जो कूरियर अपडेट भेजते हैं, उनके लिए जाँचें कि Webhook URL कूरियर के यहाँ पंजीकृत है: कूरियर लॉग प्राप्त हुआ हर अपडेट दिखाता है, या किसी को अस्वीकार क्यों किया गया (उदाहरण के लिए गलत सीक्रेट)। अन्य कूरियर की जाँच कूरियर सेटिंग्स की समय-सारणी पर होती है, और "अभी स्थिति जाँचें" तुरंत पूछता है।',
