'Cr_Guide_A_Stuck' => 'कूरियर ने पिछली जाँचों को अस्वीकार कर दिया; कारण शिपमेंट पर और कूरियर लॉग में है। बार-बार विफलताओं के बाद शिपमेंट की जाँच स्वचालित रूप से नहीं होती: कारण ठीक करें, फिर "अभी स्थिति जाँचें" का उपयोग करें।',
