'Tfa_Guide_Lead' => 'टू-फ़ैक्टर प्रमाणीकरण (2FA) साइन-इन में एक दूसरा चरण जोड़ता है: पासवर्ड के बाद, कर्मचारी अपने फ़ोन के ऑथेंटिकेटर ऐप से 6-अंकीय कोड टाइप करते हैं। चोरी हुआ या अनुमानित पासवर्ड अब प्रवेश के लिए पर्याप्त नहीं है।',
