'Tfa_Guide_Enable_1' => 'प्रोफ़ाइल खोलें (ऊपर दाईं ओर अवतार मेनू) और "टू-फ़ैक्टर प्रमाणीकरण" कार्ड खोजें।',
'Tfa_Guide_Enable_2' => '"चालू करें" पर क्लिक करें और वर्तमान पासवर्ड से पुष्टि करें।',
'Tfa_Guide_Enable_3' => 'ऐप से QR कोड स्कैन करें, या उसके नीचे दिखाई गई कुंजी टाइप करें।',
'Tfa_Guide_Enable_4' => 'पूरा करने के लिए ऐप में दिखाया गया 6-अंकीय कोड दर्ज करें।',
'Tfa_Guide_Open_Profile' => 'मेरी प्रोफ़ाइल खोलें',
'Tfa_Guide_Codes_Title' => 'रिकवरी कोड सहेजें',
'Tfa_Guide_Codes_Text' => 'सेटअप के तुरंत बाद, 8 रिकवरी कोड एक बार दिखाए जाते हैं। प्रत्येक कोड फ़ोन कोड की जगह एक बार काम करता है — खोए, टूटे या रीसेट किए गए फ़ोन के लिए। इन्हें डाउनलोड या कॉपी करें और फ़ोन से दूर किसी सुरक्षित स्थान पर रखें।',
'Tfa_Guide_Codes_Note' => 'कोड कम बचे हैं? प्रोफ़ाइल पर "नए रिकवरी कोड" पूरा सेट बदल देता है; पुराने कोड काम करना बंद कर देते हैं।',
'Tfa_Guide_Signin_Title' => 'साइन इन करना',
'Tfa_Guide_Signin_Text' => 'Email और पासवर्ड के बाद, लॉगिन पेज ऐप से वर्तमान कोड माँगता है। कोड हर 30 सेकंड में बदलते हैं और प्रत्येक कोड एक बार काम करता है।',
'Tfa_Guide_Signin_Trust' => '"इस डिवाइस पर दोबारा न पूछें" पर टिक करने से उस ब्राउज़र पर :days दिनों तक कोड नहीं माँगा जाता।',
'Tfa_Guide_Signin_Recovery' => 'फ़ोन पास में नहीं है? "रिकवरी कोड का उपयोग करें" पर क्लिक करें और सहेजे गए कोड में से एक टाइप करें।',
'Tfa_Guide_Admin_Title' => 'व्यवस्थापकों के लिए',
'Tfa_Guide_Require_Title' => 'इसे अनिवार्य बनाएँ',
'Tfa_Guide_Require_Text' => 'इस कार्ड पर "टू-फ़ैक्टर प्रमाणीकरण अनिवार्य करें" चालू करें, फिर वे भूमिकाएँ चुनें जिन्हें इसका उपयोग करना होगा — या हर उपयोगकर्ता के लिए सूची खाली छोड़ें। सहेजने के लिए सबमिट करें पर क्लिक करें।',
'Tfa_Guide_Require_Next' => 'किसी को साइन आउट नहीं किया जाता। जिन उपयोगकर्ताओं के पास अभी 2FA नहीं है, उन्हें अगले साइन-इन पर प्रवेश से पहले लॉगिन पेज पर सेटअप कराया जाता है, और वहीं उन्हें अपने रिकवरी कोड दिखते हैं।',
'Tfa_Guide_Require_Note' => 'जिन उपयोगकर्ताओं के लिए यह अनिवार्य है, वे इसे अपनी प्रोफ़ाइल से बंद नहीं कर सकते।',
'Tfa_Guide_Trust_Title' => 'विश्वसनीय डिवाइस',
'Tfa_Guide_Trust_Text' => '"विश्वसनीय डिवाइस याद रखें" यह तय करता है कि सफल साइन-इन के बाद कोई ब्राउज़र कितने समय तक कोड छोड़ सकता है। साझा या सार्वजनिक कंप्यूटर, जैसे दुकान का POS, के लिए "हमेशा कोड माँगें" चुनें।',
'Tfa_Guide_Trust_Note' => 'संख्या कम करने से पहले से विश्वसनीय डिवाइस की अवधि भी घट जाती है; 2FA बंद करने या रीसेट करने पर सभी भुला दिए जाते हैं।',
'Tfa_Guide_Lost_Title' => 'फ़ोन खो गया और रिकवरी कोड नहीं हैं',
'Tfa_Guide_Lost_Text' => 'उपयोगकर्ता पेज पर, 2FA वाले उपयोगकर्ताओं के 2FA कॉलम में "चालू" दिखता है। कार्रवाई में शील्ड बटन इसे रीसेट करता है: उपयोगकर्ता केवल पासवर्ड से साइन इन करता है और ऐप दोबारा सेट अप करता है (या अनिवार्य होने पर उससे ऐसा करने को कहा जाता है)।',
'Tfa_Guide_Lost_Warn' => 'रीसेट करने से पहले पुष्टि करें कि अनुरोध कौन कर रहा है — रीसेट उस खाते से 2FA की सुरक्षा हटा देता है।',
'Tfa_Guide_Open_Users' => 'उपयोगकर्ता खोलें',
'Tfa_Guide_Mobile_Title' => 'मोबाइल ऐप और API',
'Tfa_Guide_Mobile_Text' => 'मोबाइल ऐप और API टोकन एंडपॉइंट भी वही कोड माँगते हैं। यदि किसी ऐसे उपयोगकर्ता के लिए 2FA अनिवार्य है जिसने इसे अभी तक सेट अप नहीं किया, तो उसे ऐसा करने के लिए एक बार वेब पर साइन इन करना होगा।',
'Tfa_Guide_Protect_Title' => 'अंतर्निहित सुरक्षा',
'Tfa_Guide_Protect_1' => '5 गलत कोड उस उपयोगकर्ता के लिए 15 मिनट तक कोड दर्ज करना ब्लॉक कर देते हैं, ऊपर की लॉकआउट सेटिंग्स चाहे जो हों।',
'Tfa_Guide_Protect_2' => 'प्रत्येक कोड और प्रत्येक रिकवरी कोड केवल एक बार काम करता है।',
'Tfa_Guide_Protect_3' => '"साइन-इन गतिविधि रिकॉर्ड करें" चालू होने पर, गलत कोड साइन-इन गतिविधि सूची में "गलत 2FA कोड" के रूप में दिखते हैं।',
'Tfa_Guide_Trouble_Title' => 'समस्या निवारण',
'Tfa_Guide_Faq_Clock_Q' => 'नए कोड के साथ भी “यह कोड मान्य नहीं है”',
'Tfa_Guide_Faq_Clock_A' => 'संभवतः फ़ोन की घड़ी गलत है। कोड समय पर निर्भर करते हैं: फ़ोन की तारीख और समय को स्वचालित (नेटवर्क समय) पर सेट करें, फिर अगला कोड आज़माएँ।',
'Tfa_Guide_Faq_Phone_Q' => 'नए फ़ोन पर जाना',
'Tfa_Guide_Faq_Phone_A' => 'या तो ऑथेंटिकेटर ऐप की अपनी ट्रांसफ़र सुविधा का उपयोग करें, या प्रोफ़ाइल पर 2FA बंद करें और नए फ़ोन के साथ फिर से चालू करें (यदि यह अनिवार्य है, तो इसके बजाय किसी व्यवस्थापक से इसे रीसेट करने को कहें)।',
'Tfa_Guide_Faq_Locked_Q' => '“बहुत अधिक अमान्य कोड”',
'Tfa_Guide_Faq_Locked_A' => 'दिखाए गए समय (15 मिनट तक) की प्रतीक्षा करें, या किसी व्यवस्थापक से उपयोगकर्ता का 2FA रीसेट करवाएँ।',
'Tfa_Guide_Faq_Key_Q' => 'सर्वर बदलने के बाद 2FA वाला कोई भी साइन इन नहीं कर पाता',
'Tfa_Guide_Faq_Key_A' => '2FA सीक्रेट .env फ़ाइल में APP_KEY से एन्क्रिप्ट किए जाते हैं। ऐप को स्थानांतरित या पुनर्स्थापित करते समय वही APP_KEY रखें; यदि यह बदल गया है, तो 2FA के बिना किसी व्यवस्थापक को प्रभावित उपयोगकर्ताओं को रीसेट करना होगा।',
'Tfa_Guide_Button' => 'गाइड',
'Tfa_Guide_Title' => 'टू-फ़ैक्टर प्रमाणीकरण गाइड',
'Sec_2fa_Pending' => ':count को अभी इसे सेट अप करना है',
'Sec_2fa_See_Who' => 'देखें कौन',
'Sec_2fa_Grace_Off' => 'कोई नहीं — अगले साइन-इन पर सेट अप करें',
'Sec_2fa_Applied' => ':count उपयोगकर्ता साइन आउट किए गए।',
'Tfa_Guide_Rollout_Title' => 'इसे हर उपयोगकर्ता के लिए लागू करें',
'Tfa_Guide_Rollout_1' => 'पहले इसे अपने खाते के लिए चालू करें (प्रोफ़ाइल), ताकि आप चरणों को जान लें।',
'Tfa_Guide_Rollout_2' => 'अपनी टीम को बताएँ कि कौन सा ऐप इंस्टॉल करना है और साइन-इन पर सेटअप में एक मिनट लगता है।',
'Tfa_Guide_Rollout_3' => '"टू-फ़ैक्टर प्रमाणीकरण अनिवार्य करें" चालू करें, "इनके लिए अनिवार्य" खाली छोड़ें (= हर उपयोगकर्ता), और वैकल्पिक रूप से एक छूट अवधि चुनें। सबमिट करें पर क्लिक करें।',
'Tfa_Guide_Rollout_4' => '"2FA के बिना उपयोगकर्ताओं को साइन आउट करें" पर क्लिक करें ताकि पहले से साइन इन लोग इसे बाद के किसी साइन-इन के बजाय अभी सेट अप करें। आप साइन इन रहते हैं।',
'Tfa_Guide_Rollout_5' => 'इस कार्ड के काउंटर से, या उपयोगकर्ता पेज पर "सेटअप आवश्यक" फ़िल्टर से प्रगति देखें।',
'Tfa_Guide_Rollout_Note' => 'छूट अवधि होने पर, सेटअप स्क्रीन समय-सीमा तक “बाद में याद दिलाएँ” दिखाती है; उसके बाद, साइन इन करने के लिए सेटअप अनिवार्य है।',
'Tfa_Guide_Customers_Title' => 'ग्राहक खाते (स्टोर और क्लाइंट पोर्टल)',
'Tfa_Guide_Customers_Text' => 'ग्राहक भी अपने खातों को सुरक्षित कर सकते हैं। यह प्रत्येक ग्राहक के लिए वैकल्पिक है और कभी थोपा नहीं जाता: इसे स्टोर सेटिंग्स → पंजीकरण एक्सेस नियंत्रण (ऑनलाइन स्टोर) और क्लाइंट पोर्टल → पोर्टल सेटिंग्स (क्लाइंट पोर्टल) में चालू करें।',
'Tfa_Guide_Customers_1' => 'ग्राहक इसे मेरा खाता (स्टोर) या प्रोफ़ाइल (पोर्टल) से चालू करते हैं।',
'Tfa_Guide_Customers_2' => 'वे Email से भेजा गया कोड चुनते हैं — सबसे आसान, किसी ऐप की ज़रूरत नहीं — या रिकवरी कोड के साथ ऑथेंटिकेटर ऐप।',
'Tfa_Guide_Customers_3' => 'Email से भेजे गए कोड के लिए सही मेल सेटिंग्स (सेटिंग्स → मेल सेटिंग्स) आवश्यक हैं। ये 10 मिनट बाद समाप्त हो जाते हैं।',
'Tfa_Guide_Customers_4' => 'बाद में विकल्प बंद करने से नए सेटअप रुक जाते हैं; जो ग्राहक पहले से इसका उपयोग करते हैं, उनसे कोड माँगा जाता रहेगा और वे इसे स्वयं बंद कर सकते हैं।',
'Tfa_Required_Grace_Notice' => 'आपके व्यवस्थापक ने टू-फ़ैक्टर प्रमाणीकरण अनिवार्य किया है। आप साइन-इन पर इसे :date तक टाल सकते हैं; उसके बाद, सेटअप अनिवार्य है।',
'Tfa_Filter_All' => '2FA: सभी उपयोगकर्ता',
'Tfa_Needs_Setup_Help' => 'सिस्टम सेटिंग्स > सुरक्षा द्वारा अनिवार्य; अगले साइन-इन पर इसे सेट अप करने को कहा जाएगा।',
'Tfa_Needs_Setup' => 'सेटअप आवश्यक',
'Tfa_Filter_On' => '2FA चालू',
'Tfa_Filter_Off' => '2FA बंद',
'Tfa_Filter_Pending' => 'सेटअप आवश्यक (अनिवार्य)',
'Store_Customer_2fa' => 'दो-चरणीय सत्यापन',
'Store_Customer_2fa_Help' => 'ग्राहकों को Email से भेजे गए कोड या ऑथेंटिकेटर ऐप के कोड से अपने खाते को सुरक्षित करने देता है, जिसे मेरा खाता से चालू किया जाता है। प्रत्येक ग्राहक के लिए वैकल्पिक।',
'Portal_2fa' => 'दो-चरणीय सत्यापन',
'Portal_2fa_Help' => 'ग्राहकों को Email से भेजे गए कोड या ऑथेंटिकेटर ऐप के कोड से अपने पोर्टल लॉगिन को सुरक्षित करने देता है, जिसे उनकी प्रोफ़ाइल से चालू किया जाता है। प्रत्येक ग्राहक के लिए वैकल्पिक।',
'Two_factor_grace_notice' => ':date से अनिवार्य। तब तक आप इसे बाद में सेट अप कर सकते हैं।',
'Two_factor_remind_later' => 'बाद में याद दिलाएँ',
'Sec_2fa_Grace' => 'छूट अवधि',
'Sec_2fa_Grace_Help' => 'उपयोगकर्ताओं को समय-सीमा तक सेटअप स्क्रीन पर “बाद में याद दिलाएँ” चुनने देता है, ताकि किसी की शिफ़्ट बीच में न रुके। अनिवार्यता चालू किए जाने के समय से गिना जाता है।',
'Sec_2fa_Grace_Ends' => 'सेटअप :date को अनिवार्य हो जाएगा।',
'Sec_2fa_Apply' => 'अभी लागू करें',
'Sec_2fa_Apply_Help' => 'पहले से साइन इन लोगों से केवल उनके अगले साइन-इन पर पूछा जाता है, जो “मुझे याद रखें” के साथ महीनों बाद हो सकता है। यह हर उस व्यक्ति को, हर डिवाइस पर, साइन आउट कर देता है जिसे 2FA सेट अप करना है और उसने नहीं किया, ताकि वे दोबारा साइन इन करते समय इसे सेट अप करें। आप साइन इन रहते हैं।',
'Sec_2fa_Apply_Confirm' => 'अभी :count उपयोगकर्ताओं को साइन आउट करें?',
'Sec_2fa_Apply_Ok' => 'उन्हें साइन आउट करें',
'Sec_2fa_Apply_Save_First' => 'पहले अपने परिवर्तन सहेजें',
'Sec_2fa_Apply_Button' => '2FA के बिना उपयोगकर्ताओं को साइन आउट करें',
'Cust_2fa_Email' => 'Email',
'Cust_2fa_App' => 'ऐप',
'Cust_2fa_Reset' => 'दो-चरणीय बंद करें',
'Cust_2fa_Reset_Title' => 'दो-चरणीय सत्यापन बंद करें?',
'Cust_2fa_Reset_Help' => 'यह ग्राहक केवल अपने पासवर्ड से साइन इन करेगा और अपने खाते से इसे फिर से चालू कर सकता है। ऐसा केवल यह पुष्टि करने के बाद करें कि अनुरोध कौन कर रहा है।',
'Reorder_Card' => 'पुनः ऑर्डर',
'Reorder_Card_Help' => 'पुनः ऑर्डर सुझावों द्वारा यह तय करने के लिए उपयोग किया जाता है कि कब और कितना खरीदना है। डिफ़ॉल्ट का उपयोग करने के लिए फ़ील्ड खाली छोड़ें।',
'Reorder_Preferred_Supplier' => 'पसंदीदा आपूर्तिकर्ता',
