'Reorder_Min_Qty' => 'न्यूनतम ऑर्डर',
'Reorder_In_Purchase_Unit' => 'खरीद इकाई में',
'Reorder_Multiple' => 'इसके गुणकों में ऑर्डर करें',
'Reorder_Excluded' => 'इस उत्पाद के लिए कभी पुनः ऑर्डर का सुझाव न दें',
'Reorder_Suggestions' => 'पुनः ऑर्डर सुझाव',
'Reorder_Settings' => 'सेटिंग्स',
'Reorder_Migration_Help' => 'पुनः ऑर्डर सेटिंग्स सक्षम करने के लिए डेटाबेस माइग्रेशन चलाएँ (php artisan migrate)।',
'Reorder_To_Order' => 'ऑर्डर करने के लिए उत्पाद',
