'Reorder_Show_All' => 'सभी उत्पाद दिखाएँ',
'Reorder_Manufactured_Help' => 'इसकी सक्रिय सामग्री सूची (BOM) है: इसे खरीदने के बजाय मैन्युफ़ैक्चरिंग में बनाएँ।',
'Reorder_Manufactured' => 'निर्मित',
