'Reorder_None_All' => 'कोई स्टॉक वाला उत्पाद इन फ़िल्टर से मेल नहीं खाता।',
'Reorder_None' => 'अभी किसी चीज़ को पुनः ऑर्डर करने की ज़रूरत नहीं है।',
