'Reorder_Settings_Title' => 'पुनः ऑर्डर डिफ़ॉल्ट',
'Reorder_Settings_Help' => 'हर उत्पाद के लिए उपयोग किया जाता है, जब तक कि उसका पुनः ऑर्डर कार्ड (उत्पाद फ़ॉर्म) अपना लीड टाइम या सुरक्षा स्टॉक निर्धारित न करे।',
'Reorder_Window' => 'औसत बिक्री की अवधि (दिन)',
'Reorder_Window_Help' => 'हाल की बिक्री जिससे यह गणना की जाती है कि प्रतिदिन कितना बिकता है।',
'Reorder_Lead_Help' => 'ऑर्डर देने और माल प्राप्त करने के बीच के दिन।',
'Reorder_Safety_Help' => 'देरी या व्यस्त सप्ताह की स्थिति के लिए रखे गए अतिरिक्त दिनों का स्टॉक।',
'Reorder_Coverage' => 'इतने दिनों के लिए ऑर्डर करें',
'Reorder_Coverage_Help' => 'पहुँचने के बाद प्रत्येक ऑर्डर कितने दिनों की बिक्री के लिए पर्याप्त होना चाहिए।',
'Reorder_How' => 'सुझाव कैसे काम करते हैं',
'Reorder_How_1' => 'पुनः ऑर्डर तब करें जब स्टॉक + खुले ऑर्डर इस स्तर तक गिर जाएँ: दैनिक बिक्री × (लीड टाइम + सुरक्षा दिन), और उत्पाद के स्टॉक अलर्ट से कभी कम नहीं।',
'Reorder_How_2' => 'लीड टाइम + सुरक्षा दिन + ऊपर दिए गए दिनों को कवर करने लायक ऑर्डर करें। हाल में बिक्री न होने वाले उत्पादों को उनके स्टॉक अलर्ट के दोगुने तक भरा जाता है।',
'Reorder_How_3' => 'मात्राएँ खरीद इकाई में होती हैं, जिन्हें उत्पाद के न्यूनतम ऑर्डर और गुणक तक ऊपर पूर्णांकित किया जाता है।',
'Reorder_Status_Out' => 'स्टॉक समाप्त',
'Reorder_Status_Critical' => 'गंभीर',
'Reorder_Status_Low' => 'कम',
